import re
from pathlib import Path

ROOT = Path('novel-writing-team/manuscript/projects/flame-of-forgetting')
SCENE_TEXT = ROOT.joinpath('scenes.md').read_text(encoding='utf-8')
MAP_TEXT = ROOT.joinpath('episode-map.md').read_text(encoding='utf-8')

scene_blocks = re.split(r'\n## Scene ', SCENE_TEXT)[1:]
scenes = {}
for block in scene_blocks:
    header, *rest = block.splitlines()
    sid = header.strip()
    data = {'id': sid}
    for line in rest:
        m = re.match(r'- ([^:]+):\s*(.*)', line)
        if m:
            data[m.group(1).strip()] = m.group(2).strip()
    scenes[sid] = data

episode_blocks = re.split(r'\n## ตอนที่ ', MAP_TEXT)[1:]
episodes = []
for block in episode_blocks:
    lines = block.splitlines()
    m = re.match(r'(\d+):\s*(.+)', lines[0])
    if not m:
        continue
    ep = int(m.group(1))
    title = m.group(2).strip()
    data = {'ep': ep, 'title': title}
    for line in lines[1:]:
        m2 = re.match(r'- ([^:]+):\s*(.*)', line)
        if m2:
            data[m2.group(1).strip()] = m2.group(2).strip()
    episodes.append(data)

PROSE = {
1: """ฝนสีแดงตกลงบนหินดำราวกับฟ้าเพิ่งควักตับตัวเองออกมาบีบทิ้งทั้งผืนเมือง ขุนอัคคียืนอยู่กลางตรอกแคบในชุดมือปราบสีเข้ม ชายเสื้อชุ่มน้ำจนแนบไปกับลำตัว แต่ท่วงท่าของเขายังนิ่งเหมือนไม่มีอะไรแตะต้องได้ ปลายดาบเพิ่งตัดเงาอสุรกายขาดไปจากประตูไม้ผุ กลิ่นไหม้ของยันต์กับกลิ่นเลือดสดคลุ้งปนกันจนคนธรรมดาคงอาเจียน ทว่าเขาเพียงช้อนสายตาขึ้นมองพยานสองคนที่ทรุดกองอยู่ข้างกำแพง แล้วก้าวเข้าไปทำงานส่วนที่พระนครชอบเรียกว่าความเมตตา

เจ้าหน้าที่กรมอาลักษณ์ยื่นผอบอาคมให้ เขารับมาด้วยมือเดียว อีกมือแตะหน้าผากชาวบ้านที่สั่นจนฟันกระทบกัน “หลับตา” เขาบอกสั้นๆ ชายคนนั้นสะอื้น “ข้าเห็นมันฉีกคนต่อหน้า ข้าไม่อยากลืม” อัคคีหยุดอยู่ชั่วหายใจหนึ่งก่อนตอบ “คืนนี้ท่านไม่ลืมก็ไม่รอด” แสงบางๆ จากคาถาลบความจำไหลจากนิ้วเขาเข้าไป พยานทรุดฮวบลงกับพื้น เจ้าหน้าที่มองตามอย่างโล่งใจ แต่ความโล่งนั้นอยู่ได้ไม่นาน เมื่อมีเสียงตะโกนจากปลายตรอกว่าเจออีกศพหนึ่งหลังร้านเตาถ่าน

ศพนอนคว่ำอยู่ในน้ำฝนแดง ครึ่งหลังถูกกรีดจนเสื้อเปิดออก เห็นรอยสักสีคล้ำกินผิวอยู่เหนือซี่โครง รอยนั้นไม่เหมือนตราโจร ไม่เหมือนยันต์ผี และไม่ควรอยู่บนร่างคนตายทั่วไปเลย เพราะเส้นโค้งที่แตกเป็นเขี้ยวและวงเพลิงเล็กตรงกลางทำให้อัคคีนึกถึงคืนเก่าๆ ที่บิดาเคยจับมือเขาวาดอักขระป้องกันตัวบนกระดานทราย เข่าของเขาแข็งอยู่ชั่ววินาที ปลายนิ้วที่เปียกฝนค้างเหนือรอยสักอย่างคนไม่กล้าแตะอดีตตัวเองตรงๆ “เรียกคนมาเก็บเงียบๆ” เจ้าหน้าที่กระซิบ “ถ้าเรื่องนี้ไปถึงหอใหญ่...”

มันไปถึงหอใหญ่เร็วเกินกว่าจะปิดได้ หลวงวิจิตรส่งคำสั่งมาผ่านตราพลันบนแผ่นทองคำ เสียงชายชราดังนุ่มในสายฝน “คดีนี้ยุติทันที เก็บศพ ลบพยาน แล้วรายงานว่าจัดการอสุรกายเสร็จสิ้น” เจ้าหน้าที่ก้มหน้ารับคำโดยอัตโนมัติ อัคคียืนนิ่งอยู่ข้างศพ รู้สึกเหมือนน้ำฝนเย็นจัดไหลเข้าไปในอกแทนที่จะผ่านผิวหนัง ชาวบ้านที่เพิ่งถูกลบความจำเงยหน้าขึ้นงงๆ ถามว่า “ข้า...มาอยู่ที่นี่ได้อย่างไร” อัคคีไม่ตอบ เขามองรอยสักบนศพอีกครั้ง แล้วรู้ว่าคืนนี้จะไม่ยอมจบง่ายอย่างที่เจ้านายสั่ง""",
2: """โรงเก็บศพลับหลังตรอกมืดกว่าเดิมเมื่อไร้เสียงฝน อัคคีวางตะเกียงลงใกล้ร่างไร้ชื่อและดึงผ้าคลุมออกช้าๆ แสงไฟสั่นบนผิวซีดของคนตาย และยิ่งสั่นหนักเมื่อไล่ไปถึงรอยสักที่แผ่คล้ายเปลวไฟคืบคลานใต้เนื้อ เขาเคยเห็นลายมือแบบนี้ครั้งสุดท้ายบนกำแพงฝึกดาบในเรือนเก่า ก่อนบิดาจะถูกตราหน้าว่าเป็นกบฏแล้วหายไปพร้อมชื่อเสียงทั้งชีวิต เมืองบอกว่าเขาควรลืมเรื่องนั้นมานานแล้ว แต่ร่างตรงหน้ากลับขุดมันขึ้นจากหลุมด้วยความง่ายดายเกินไป

เจ้าหน้าที่กรมอาลักษณ์คนเดิมยืนเฝ้าประตู มือสั่นอยู่บนด้ามมีดสั้น “ท่านขุน เราควรเผามันเสียก่อนเช้า” เขาพูดเบาราวกลัวศพได้ยิน อัคคีก้มลงพลิกแขนคนตาย พบคราบเขม่าดำฝังตามซอกเล็บเหมือนเคยจับเหล็กร้อนจัดมานาน “ถ้าเผาเร็วเกินไป เราจะไม่มีอะไรเหลือให้ตรวจ” เจ้าหน้าที่กลืนน้ำลาย “คำสั่งท่านหลวงคือ—” “ข้าฟังอยู่” อัคคีตัดบทโดยไม่เงยหน้า น้ำเสียงเรียบจนคนฟังไม่รู้ว่าควรถอยหรือเถียงต่อ เขาใช้ปลายมีดเขี่ยชายผ้าพันเอวศพ เจอเศษแผ่นทองบางเท่าเล็บติดอยู่ข้างใน ราวกับคนตายพยายามซ่อนมันจากใครบางคนในวินาทีสุดท้าย

เมื่อเขายกเศษทองขึ้นรับแสง ตรากรมอาลักษณ์เล็กๆ บนนั้นก็วาบผ่านสายตา ใจที่เขาพยายามกดไว้เย็นวาบลงไปถึงท้อง หลวงวิจิตรไม่ได้สั่งปิดเพราะคดีเล็กเกินดู หากเพราะมันใกล้เกินแตะมือคนในหอ เจ้าหน้าที่ก้าวเข้ามาอีกก้าว “ท่านขุน ปล่อยเถอะ เรื่องบางเรื่องไม่คุ้มให้คนเป็นตายตาม” อัคคีหัวเราะในลำคอเบามากจนแทบไม่ใช่เสียงหัวเราะ “คนตายตรงนี้ก็คงถูกบอกแบบนั้นเหมือนกัน” เขาพับเศษทองเก็บใส่อกเสื้อ แล้วคลุมศพกลับอย่างระวังเกินเหตุ เหมือนอีกฝ่ายยังมีศักดิ์ศรีเหลือให้รักษา

ก่อนไก่จะขัน เขาออกจากโรงเก็บศพพร้อมความเงียบหนักในอก ประตูไม้เก่าปิดตามหลังดังครืดเดียว แต่เสียงนั้นเหมือนตัดชีวิตเดิมของเขาออกไปอีกชั้น ใต้ชายคาที่น้ำยังหยดจากปลายหลังคา อัคคีเงยหน้ามองความมืดปลายตรอก และในม่านฝนที่ซาแล้ว เขาเห็นเงาชายสูงคนหนึ่งยืนอยู่ไกลๆ ไหล่กว้าง ท่ายืนหนักแน่นอย่างคนคุ้นเคย เงานั้นหันมาเพียงเสี้ยวหน้า ก่อนจะละลายไปกับเงากำแพง “พ่อ...” คำหนึ่งหลุดจากปากเขาโดยไม่ทันระวัง เมื่อมันเงียบหาย เขาก็รู้ว่าต่อให้คนทั้งเมืองสั่งให้ลืม คดีนี้ก็กลายเป็นเรื่องของเขาไปแล้ว""",
3: """เรือนรำหลวงเงียบกว่าศาลเจ้าในคืนมีศพ เสียงข้อเท้ากระทบไม้ของนางรำหายไปหมด เหลือเพียงกลิ่นเครื่องหอมเก่าที่อบค้างอยู่ตามเสาและม่านโปร่ง ขุนอัคคีเดินผ่านห้องซ้อมที่มืดสนิทไปถึงห้องเล็กด้านใน ที่นั่นสาลิกานั่งรออยู่หน้าโต๊ะเตี้ย ปลายนิ้วข้างหนึ่งเปื้อนเลือดแห้งเพียงหยดเดียว นางเงยหน้ามองเขาอย่างคนรู้ว่าผู้มาเยือนไม่ได้มาขอความช่วยเหลืออย่างสุภาพนัก “ท่านทำหน้าเหมือนกำลังจะจับโจร ไม่ใช่กำลังมาขอให้ข้าช่วย” นางพูด

อัคคีวางสมุดปกดำกับเศษทองลงบนโต๊ะ “ข้าต้องการคำตอบ” สาลิกาไม่แตะของทั้งสองสิ่งในทันที นางมองหน้าเขานานพอให้เจ้าของสายตาต้องเมินไปทางหน้าต่าง “แล้วข้าจะได้อะไรจากคำตอบนั้น” เขาชะงัก เพราะไม่ชินกับการที่ใครถามราคาความเสี่ยงต่อหน้า “ได้รู้ว่ามีคนอีกคนในเมืองนี้ไม่อยากให้เรื่องมันเงียบ” เขาตอบ ในที่สุดนางก็ยิ้มบางๆ เหมือนประโยคนี้พอฟังได้ นางแตะเลือดบนเศษทอง เขียนวงเล็กบนฝ่ามือตัวเอง แล้วหลับตา

ลมหายใจของสาลิกาเปลี่ยนไปก่อนภาพจะมา นางขมวดคิ้วแน่น นิ้วอีกข้างจิกขอบโต๊ะจนข้อนิ้วซีด “ข้าเห็นป้ายหินแตก...หมอกหนา...แล้วมีประตูอยู่ใต้ดิน” เสียงนางเบาลงเรื่อยๆ “ประตูนั้นมีตรากรมอาลักษณ์” อัคคีเผลอก้าวเข้าไปใกล้ “ที่ไหน” สาลิกาเม้มปากเหมือนฝืนยกของหนักขึ้นทั้งร่าง “นอกแผนที่หลวง” แล้วทันใดนั้นนางก็สะดุ้ง ลืมตาขึ้นพร้อมเลือดเส้นบางที่ซึมจากมุมตา “มีคนลบสถานที่นั้นออกไปโดยเจตนา” เขายื่นผ้าให้ นางไม่รับทันที แต่พึมพำเหมือนพูดกับตัวเอง “สิ่งที่ถูกซ่อนเก่งที่สุด มักเป็นสิ่งที่คนซ่อนไม่กล้ามองเอง” 

อัคคีเก็บสมุดกับเศษทองกลับเข้าชายเสื้อ ขณะเดียวกันก็ได้ยินเสียงรองเท้าเบาๆ หยุดอยู่หลังบานประตู หลวงวิจิตรไม่ได้เปิดเข้ามา เพียงเอ่ยจากด้านนอกด้วยเสียงสุภาพเกินจริง “การทำงานนอกระเบียบยามวิกาล ชวนให้ข้าเป็นห่วงเสมอ” สาลิกาช้อนตาขึ้นมองอัคคีโดยไม่พูด ทั้งคู่รู้พร้อมกันว่าความลับเริ่มมีกลิ่นแรงเกินซ่อนได้แล้ว อัคคีตอบกลับไปทางประตู “ห่วงงานของท่านเถอะขอรับ” ชั่วครู่หนึ่งความเงียบตึงขึ้นเหมือนสายพิณถูกดึงจนใกล้ขาด แล้วเขาก็ออกจากเรือนรำไปพร้อมพิกัดที่ไม่ควรมีอยู่บนโลกนี้""",
4: """บันทึกลับแนบอยู่ใต้เสื้อชั้นในจนขอบกระดาษบาดผิวทุกครั้งที่อัคคีหายใจแรง เขาเข้าเฝ้าหลวงวิจิตรในห้องเอกสารยามเช้า กลิ่นหมึกกับกระดาษเก่าแห้งสนิทจนชวนให้นึกถึงสถานที่ซึ่งไม่เคยมีเลือดเปื้อน ทั้งที่คนจำนวนมากคงถูกตัดสินชะตาในห้องนี้มานานแล้ว หลวงวิจิตรนั่งหลังตรงอยู่หลังโต๊ะ นิ้วเรียวยาวลูบขอบแฟ้มให้เสมอกันก่อนพูด “ขุนอัคคี เจ้าเหนื่อยจากคดีเมื่อคืนแล้ว กระมัง” น้ำเสียงเหมือนถามไถ่ แต่สายตาเหมือนคนกำลังนับรอยเปื้อนบนรองเท้าของเขา

“ข้ายังทำงานได้” อัคคีตอบ หลวงวิจิตรยิ้มบาง “ดี เพราะข้ามีงานชายแดนให้เจ้า หมู่บ้านหนองชันเกิดเหตุผีระบาดเล็กน้อย พยานแตกตื่น ข่าวลือเริ่มบาน สิ่งที่เราต้องการคือความเรียบร้อย” คำสุดท้ายนั้นถูกวางลงช้าๆ ราวมีน้ำหนักมากกว่าคำอื่น เขาเลื่อนตราเดินทางกับคำสั่งปิดผนึกมาให้ อัคคีแตะกระดาษเพียงปลายนิ้ว “แค่ผีระบาด เหตุใดต้องใช้ข้า” “เพราะเจ้าเก่งเรื่องงานสกปรกโดยไม่ทำให้ดูสกปรก” หลวงวิจิตรตอบตรงอย่างสุภาพเกินไป จนประโยคนั้นฟังคล้ายคำชมและคำเตือนในคราวเดียว

ระหว่างออกจากหอ เขาพบสาลิกาเดินสวนมาตามระเบียง นางอยู่ในชุดเรียบกว่าวันก่อน ดวงตาใต้แพขนตายังแดงนิดๆ จากการอ่านเลือด “เขาส่งท่านไปแล้วหรือ” นางถาม อัคคีชะงัก “ท่านรู้?” สาลิกามองไปยังขบวนเสมียนที่เดินผ่านแล้วลดเสียงลง “คนที่รีบพาใครออกนอกเมือง มักไม่อยากให้คนนั้นถามคำถามต่อในเมือง” เขามองนางอยู่ครู่หนึ่ง ก่อนตัดสินใจยื่นสมุดปกดำให้ “เก็บไว้ก่อน ถ้าข้าไม่กลับมา...” สาลิกาไม่รับ “อย่าพูดเหมือนไปตาย ถ้าท่านอยากได้คำตอบ ก็จงกลับมาถามต่อด้วยตัวเอง” นางพูดเบาแต่หนักพอให้เขาต้องเก็บสมุดกลับ

รถม้าหลวงพาอัคคีออกจากประตูเมืองตอนบ่าย ฟ้าเหนือพระนครสว่างจัดเกินปกติจนเขารู้สึกระแวง แผลจากขอบกระดาษใต้เสื้อยังแสบอยู่ทุกครั้งที่ล้อรถกระแทกหลุม เขาเปิดคำสั่งอีกครั้ง มีเพียงถ้อยคำราชการเรียบๆ เรื่องระงับเหตุและดูแลพยาน ไม่มีคำว่าเก็บ ไม่มีคำว่าลบ ทว่าช่องว่างระหว่างบรรทัดกลับส่งกลิ่นคาวชัดกว่าคืนเจอศพ เขาพับมันเก็บอย่างช้าๆ แล้วมองทางที่ทอดยาวไปยังหนองชัน พลันนึกได้ว่าในแผนที่ทางการ พื้นที่แถบนั้นอยู่ไม่ไกลจากพิกัดที่สาลิกาเห็นในเลือดเลยแม้แต่น้อย""",
5: """หนองชันต้อนรับพวกเขาด้วยโคลนแดงที่หนึบติดรองเท้าจนทุกก้าวเหมือนมีมือจากพื้นดินดึงไว้ บ้านไม้ทั้งหมู่บ้านปิดเงียบ ทั้งที่ยังเป็นบ่ายและควรมีควันข้าวลอยจากครัว สาลิกาก้าวลงจากรถตามหลังอัคคี นางยกชายกระโปรงหนีน้ำขังแล้วชะงักเมื่อเห็นเด็กหญิงคนหนึ่งยืนกอดเสาเรือน มองผู้หญิงวัยกลางคนที่ร้องไห้อยู่ตรงหน้าเหมือนมองคนแปลกหน้า “แม่บอกว่าหนูเป็นลูก...แต่หนูจำหน้าแม่ไม่ได้” เด็กคนนั้นพูดเสียงใสเกินไปสำหรับประโยคแบบนั้น

อัคคีถามชื่อ นางตอบว่ามะลิ แล้วเงยหน้าขึ้นมองเขาตรงๆ ดวงตาเด็กไม่มีท่าทางโกหก มีแต่ความว่างชนิดที่ชวนให้คนดูเจ็บตาม “แล้วหน้าพ่อหนูหายไปไหน” คำถามนั้นทำให้สาลิกาเม้มปากแน่น ส่วนอัคคีรู้สึกเหมือนมีใครกรีดรอยแผลเก่าที่อกโดยไม่ต้องใช้มีด เจ้าหน้าที่รัฐที่มาถึงก่อนรีบอธิบายว่าชาวบ้านเพียงตกใจจากผีระบาด จำอะไรสับสนชั่วคราว พรุ่งนี้ก็จะมีพิธีปลอบขวัญและล้างอาถรรพ์ให้เรียบร้อย คำอธิบายนั้นฟังสะอาดดีเกินกว่าจะเชื่อ เมื่อมองไปรอบๆ อัคคีเห็นคนแก่สองคนทวนชื่อหลานซ้ำไปมา ราวกลัวว่าถ้าหยุดพูดแล้วชื่อจะหลุดหายไปจริงๆ

สาลิกาขอเข้าไปดูบ้านหลังที่เกิดเหตุ นางเดินช้าลงทุกก้าวเหมือนอากาศในเรือนแน่นกว่าข้างนอก บนพื้นยังมีคราบเลือดถูกขัดจนจาง อัคคีนั่งยองข้างรอยนั้นและเห็นปลายนิ้วตัวเองสั่นโดยไม่รู้ตัว “นี่ไม่ใช่ผลจากผีอย่างเดียว” สาลิกาพูดเบาๆ “มีอาคมลบความจำทับอยู่ด้วย” เขาเงยหน้ามองทันที นางสบตาเขาตรงๆ เป็นครั้งแรกในวันนั้น “ท่านไม่ได้มาที่นี่เพื่อฆ่าผีอย่างเดียวใช่หรือไม่” เขาไม่ตอบ เพราะคำตอบเริ่มชัดเกินจะโกหกคนอื่นได้ และน่ากลัวเกินจะยอมรับกับตัวเองตรงๆ

เย็นวันนั้นอัคคียืนดูดวงอาทิตย์กลืนลงหลังป่า พร้อมฟังเจ้าหน้าที่อ่านรายชื่อบ้านที่จะเข้า “เก็บกวาด” ตอนค่ำ ถ้อยคำทางราชการทำให้ทุกอย่างฟังเป็นระเบียบ แต่มะลิที่ยืนกำชายเสื้อเขาไว้แน่นทำให้คืนนั้นไม่อาจเป็นเพียงงานอีกชิ้นได้ เด็กเงยหน้าถามเบาๆ “ถ้าหนูจำหน้าพ่อไม่ได้ ท่านช่วยจำแทนหนูได้ไหม” อัคคีมองมือเล็กที่เกาะแขนเสื้อเขาแน่น แล้วรู้สึกว่าคำสั่งในอกเสื้อหนักขึ้นราวทำจากหิน""",
6: """สาลิกานั่งคุกเข่าอยู่กลางเรือนร้างในแสงตะเกียงสั่นๆ ข้างหน้าคือน้ำเลือดที่ขูดมาจากร่องพื้น เธอรู้ตั้งแต่วางนิ้วลงไปแล้วว่ารอบนี้จะหนักกว่าทุกครั้ง เพราะเลือดนี้ไม่ได้บันทึกแค่ความตาย มันบันทึกการลืมด้วย อัคคียืนเฝ้าอยู่ข้างประตู ไหล่กว้างขวางลมเย็นจากนอกเรือนไว้ครึ่งหนึ่ง “พอไม่ไหวก็หยุด” เขาพูด สาลิกาหัวเราะแผ่ว “ถ้าคนอย่างท่านพูดคำนี้ช้าไปอีกนิด ข้าคงซาบซึ้งกว่านี้” แล้วนางก็หลับตา

ภาพถาโถมเข้ามาแรงจนแทบฉีกกระดูกตาออกจากเบ้า นางเห็นชาวบ้านถูกต้อนเรียงกัน เห็นตราเดียวกับกรมอาลักษณ์เรืองขึ้นเหนือขันน้ำมนตร์ เห็นคนที่รอดจากเหตุคืนนั้นถูกแตะหน้าผากทีละคน ก่อนบางคนจะไม่ตื่นขึ้นมาอีกเลย สาลิกาสะดุ้งแรงจนเกือบล้ม เลือดไหลจากหางตาเป็นสาย อัคคีพุ่งเข้ารับตัวไว้ “พอแล้ว” เขากระชากผ้าออกมากดให้ นางจับข้อมือเขาแน่นเหมือนกลัวสติจะหลุด “ไม่พอ” เสียงเธอสั่น “คนที่รอด ถูกกำหนดให้ลืม...แล้วค่อยตายตามทีหลัง” คำสุดท้ายแทบเป็นลมหายใจ

อัคคีชะงักเหมือนโดนทุบกลางอก เขาหันไปมองนอกเรือน เห็นหมู่บ้านทั้งหมู่บ้านมืดลงพร้อมกันทีละหลัง ไม่ใช่เพราะคนเข้านอน แต่เพราะเจ้าหน้าที่เริ่มลงมือ “สั่งให้รวมพยานคืนนี้” เขาพึมพำกับตัวเองมากกว่าพูดกับใคร มะลิที่แอบตามเข้ามายืนตัวแข็งอยู่หลังเสา เด็กมองสาลิกาด้วยตาโต “เจ็บไหม” นางพยายามยิ้มให้ “เจ็บสิ แต่ยังจำได้อยู่” เด็กเงียบไปครู่หนึ่งก่อนถามด้วยเสียงบาง “ถ้าหนูต้องลืมอีก ท่านช่วยบอกหนูทีว่าใครทำ” ประโยคนั้นแหลมคมกว่ามีดใดในห้อง

คืนนั้นอัคคีออกจากเรือนพร้อมดาบที่หนักกว่าเดิม เขาสั่งให้มะลิอยู่กับสาลิกา แต่ตัวเองไม่อาจหันหลังให้สิ่งที่เพิ่งรู้ได้อีกแล้ว ไกลออกไปมีแสงคบเพลิงขยับเป็นแนวเรียงเหมือนงูไฟเลื้อยเข้าหมู่บ้าน และเป็นครั้งแรกในรอบหลายปีที่เขามองคนของรัฐด้วยสายตาเดียวกับที่เคยมองอสุรกาย""",
7: """คบเพลิงของกรมอาลักษณ์ล้อมหนองชันไว้ทีละด้านจนหมู่บ้านดูเหมือนเกาะเล็กกลางทะเลไฟ หัวหน้าหน่วยกางรายชื่อบ้านบนโต๊ะชั่วคราวหน้าศาลาแล้วสั่งการด้วยน้ำเสียงเรียบ “เริ่มจากเรือนพยานหลัก ใครยังมีอาการจำได้ผิดปกติ ให้จัดการตามระเบียบ” คำว่า ‘จัดการ’ หล่นลงพื้นอย่างเย็นชา ขุนอัคคียืนฟังอยู่ข้างๆ พลางรู้สึกว่าทุกบทเรียนที่เคยท่องเรื่องความสงบของเมืองเริ่มเน่าอยู่ในคอ เขาถามเรียบๆ “เด็กด้วยหรือ” นายทหารเหลือบตามา “เด็กยิ่งต้องทำให้เรียบร้อยเร็ว”

เขาเดินไปตามบ้านที่ถูกเปิดประตูค้น เห็นชาวบ้านบางคนยังไม่ทันเข้าใจว่าตัวเองทำผิดอะไร ก็ถูกจับกดให้นั่งคุกเข่ารับคาถา มะลิหลบอยู่หลังโอ่งน้ำ เปื้อนโคลนถึงแก้ม สายตาเธอมองเขาเหมือนมองคำตอบสุดท้ายของโลก “ท่านจะให้หนูลืมอีกไหม” เด็กถาม อัคคียกมือขึ้นตามสัญชาตญาณเดิม ปลายนิ้วค้างอยู่เหนือหน้าผากเล็กที่ยังร้อนจากไข้ เขานึกถึงคืนนับไม่ถ้วนที่ทำแบบนี้กับคนแปลกหน้าโดยไม่เคยถามชื่อ แต่เมื่อมะลิหลับตารออย่างยอมแพ้ หัวใจเขากลับกระตุกแรงจนมือชาวูบ

สาลิกามาถึงข้างหลังโดยไม่มีเสียงฝีเท้า “ถ้าท่านทำ นางก็จะเหลือแต่ความกลัวเปล่าๆ” นางพูดเบาๆ ไม่ได้ห้าม ไม่ได้อ้อนวอน แค่พูดความจริงออกมาตรงกลางความมืด อัคคีมองมะลิอีกครั้ง ก่อนลดมือลงช้าๆ เด็กสาวลืมตา มองเขาอย่างไม่แน่ใจว่ารอดแล้วจริงหรือยัง หัวหน้าหน่วยที่เห็นเหตุการณ์เดินเข้ามา “ท่านขุน กำลังทำอะไร” อัคคีตอบโดยไม่หันไป “ตรวจอาการ” แต่ในอกของเขา รอยแยกระหว่างหน้าที่กับสิ่งที่ยังพอเรียกว่ามนุษย์ได้กว้างขึ้นทุกลมหายใจ

เมื่อเสียงหวีดสัญญาณดังจากชายป่า หน่วยล่าก็เริ่มขยับเข้าประจำจุด อัคคีรู้ว่าหลังสัญญาณที่สองจะไม่มีใครในหมู่บ้านนี้เหลือสิทธิจำอะไรได้อีก เขามองมะลิที่เกาะข้อมือเขาไว้แน่น มองสาลิกาซึ่งแม้ดวงตายังแดงก็ไม่ยอมหลบสายตา แล้วจู่ๆ ก็รู้ว่าตัวเองกำลังยืนอยู่ตรงเส้นที่ข้ามเมื่อไร ชายผู้รับใช้รัฐจะตายไปทันที""",
8: """สัญญาณที่สองดังขึ้นพร้อมเสียงฝนกระหน่ำหมู่บ้านจนมองอะไรพร่าไปหมด หัวหน้าหน่วยชักดาบและก้าวตรงมาหามะลิ “เด็กคนนี้อยู่ในรายชื่อ” เขาพูดเหมือนกำลังพูดถึงข้าวของชิ้นหนึ่ง อัคคีขยับมายืนบังโดยไม่คิด “ถอยไป” นายทหารชะงัก “ท่านขุน?” คำเรียกนั้นมีทั้งความงุนงงและโกรธ เขาไม่ตอบด้วยคำพูด มือเพียงจับด้ามดาบแน่น แล้วหันคมเหล็กไปทางคนของตัวเองเป็นครั้งแรกในชีวิต

ทุกอย่างหลังจากนั้นสั้นและเร็วอย่างฝันร้าย ดาบของหัวหน้าหน่วยพุ่งก่อน เขารับ ปัด แล้วสวนกลับเข้าใต้ชายโครงในจังหวะเดียว เลือดอุ่นสาดขึ้นหน้าแขนขณะที่อีกฝ่ายทรุดเข่าลงกลางโคลน เสียงรอบตัวเงียบไปชั่วขณะเพราะไม่มีใครเชื่อสายตาตนเอง “พาเด็กไป” อัคคีสั่ง สาลิกาคว้ามือมะลิแล้ววิ่งออกทางหลังเรือน ลูกธนูอาคมพุ่งมาปักเสาไม้เหนือหัว เขาหันกลับฟันสกัดอีกสองคนก่อนถอยตาม ทั้งหมู่บ้านแตกเป็นเสียงกรีดร้องกับเสียงฝนในคราวเดียว

พวกเขาหนีเข้าป่าด้านเหนือในความมืดที่หนาทึบกว่าปกติ มะลิสะดุดหลายครั้งจนต้องให้อัคคีอุ้ม สาลิกาวิ่งนำทั้งที่หอบจนไหล่สั่น “ทางนี้” นางชี้ผ่านม่านหมอกไปยังเงาหินสูงคล้ายป้ายศพยักษ์ ซึ่งไม่ปรากฏอยู่ในแผนที่ใดที่อัคคีเคยเห็น คนของรัฐตามมาห่างๆ พร้อมเสียงสุนัขล่า “ถ้าเข้าป่านั้น เราอาจไม่ออกมาเหมือนเดิม” สาลิกาบอก เขามองกลับไปยังแสงคบเพลิงที่ใกล้เข้ามา แล้วตอบสั้นๆ “ถ้าอยู่ต่อ เราไม่มีทางออกเลย” 

เมื่อก้าวพ้นหลักหินแรก ความเงียบก็ครอบลงมาทันที ราวป่าช้าต้องห้ามกลืนเสียงโลกภายนอกไว้หมด มะลิซุกหน้ากับบ่าเขา ตัวสั่นไม่หยุด สาลิกาหอบอยู่ข้างป้ายหินแตกครึ่ง ดวงตาคู่นั้นมองความมืดตรงหน้าราวจำมันได้จากเลือดก่อนใคร “แผนที่ที่ถูกลบ เริ่มตรงนี้” นางกระซิบ อัคคีกระชับแขนที่ประคองเด็กไว้แน่นขึ้น แล้วพาพวกเขาก้าวเข้าไปในที่ที่แม้รัฐยังเลือกซ่อนไว้จากตัวเอง""",
9: """หมอกในป่าช้าต้องห้ามหนาพอจะกลืนแม้แต่เสียงฝีเท้า ต้นงิ้วดำยืนเอียงเหมือนคนถูกแขวนคอมานานจนลืมวิธีตรงตัว มะลิหลับไปแล้วบนหลังอัคคีเพราะความเหนื่อยและไข้ ส่วนสาลิกาเดินนำช้าๆ มือแตะอากาศราวคลำหารอยของสิ่งที่มองไม่เห็น “เลือดยังพาเราไปทางนี้” นางพูด อัคคีมองป้ายหินแตกครึ่งที่โผล่พ้นหมอก ด้านบนลบชื่อคนตายจนเหลือเพียงรอยขูดลึก ความตั้งใจลบชื่อจากหินกับจากหัวคน ไม่ได้ต่างกันเท่าไรนัก

พวกเขาหยุดที่ลานเล็กใต้ต้นงิ้วซึ่งรากโผล่บิดเหมือนนิ้วคนกำลังงอขอความช่วยเหลือ สาลิกาคุกเข่าลงแตะคราบแดงที่เกาะตามซอกหิน แล้วหลับตาอีกครั้ง คราวนี้ภาพไม่กระแทกนางรุนแรงเหมือนที่หนองชัน แต่ออกจะเย็นจนขนลุก “มีคนแบกศพลงไปใต้ดินหลายครั้ง” นางบอก “ทุกครั้งมีตราหลวงติดมาด้วย” อัคคีปลดมะลิลงนั่งพิงหิน แล้วใช้ดาบเขี่ยดินตามรอยที่นางชี้ ไม่นานปลายเหล็กก็กระทบแผ่นหินกลวงดังทึบ

เมื่อขูดมอสออก พวกเขาเห็นขอบประตูซ่อนอยู่ใต้ป้ายศพแตกจริงๆ ตรงกลางเป็นตรากรมอาลักษณ์ที่ถูกตีตอกลึกจนแม้กาลเวลาก็กัดไม่หมด อัคคีหัวเราะหยันในลำคอ “ห้ามคนทั้งเมืองมาที่นี่ แต่กลับตีตราตัวเองไว้หน้าประตู” สาลิกาเงยหน้ามองเขา “คนมีอำนาจมักเชื่อว่าถ้าไม่มีใครกล้ามอง ความผิดก็เท่ากับไม่มี” มะลิสะดุ้งตื่นเพราะลมเย็นจากรอยแยกใต้หิน นางกอดแขนเขาแน่น “ข้างล่างมีอะไร” เด็กถาม อัคคีสบตาสาลิกา ก่อนตอบอย่างซื่อที่สุดในคืนยาวหลายคืน “ข้ายังไม่รู้ แต่คงไม่ใช่สิ่งที่อยากให้ใครจำได้” 

ประตูยังไม่เปิด ทว่าการได้เห็นมันก็เพียงพอจะเปลี่ยนทุกอย่างแล้ว เพราะมันหมายความว่าความลับนี้ไม่ได้เป็นข่าวลือหรือภาพจากเลือดอีกต่อไป มันมีบานพับ มีรอยใช้ มีหนทางลงจริงอยู่ใต้เท้าพวกเขา และคนที่สร้างมันคือคนเดียวกับที่สั่งให้เขาลบความจำทั้งชีวิต""",
10: """พออัคคีกดตราเปิดตามร่องอักขระ แผ่นหินก็ครางต่ำเหมือนสัตว์ป่วยก่อนค่อยๆ แยกออก ลมหายใจแรกจากใต้ดินพุ่งขึ้นมาเย็นเฉียบและมีกลิ่นเลือดตากบนเหล็กจนมะลิยกมือปิดจมูก สาลิกาซีดลงทันที “ที่นี่อาคมหนามาก” นางเตือน แต่คนที่เปิดประตูแล้วไม่มีสิทธิถอยก็ได้แต่ชูตะเกียงก้าวนำลงบันไดชื้นแคบไปก่อน เด็กหญิงถูกฝากให้นอนซ่อนในโพรงรากไม้พร้อมยันต์ป้องกันชั่วคราว เพราะสิ่งที่รออยู่ข้างล่างอาจหนักเกินให้เด็กเห็น

บันไดพาพวกเขาลงสู่ความมืดที่เล่นกลกับความทรงจำ ทุกสิบก้าวอัคคีจะเห็นภาพแวบของเรือนเก่า เห็นมือบิดาวางบนบ่าตนแล้วหายไป พอลืมตาอีกครั้งก็เหลือแต่ผนังหินชื้น สาลิกาเองก็เดินช้าลงเรื่อยๆ จนต้องจับแขนเขาไว้ “ถ้าข้าพูดชื่อใครผิด อย่าปล่อยมือ” นางกระซิบ เขาหันไปมองนางแล้วพยักหน้า “ถ้าข้าจำท่านผิดล่ะ” สาลิกาถามต่อ ทั้งที่พยายามพูดเล่นแต่เสียงสั่น อัคคีตอบหลังเงียบไปครู่หนึ่ง “ข้าจะเรียกเอง” คำตอบสั้นๆ นั้นทำให้นางกำชายเสื้อเขาแน่นขึ้นโดยไม่รู้ตัว

กลางทางเดินมีภาพหลอนแรงขึ้นจนแทบทำให้ทั้งคู่หันดาบใส่กัน อัคคีเห็นสาลิกากลายเป็นเจ้าหน้าที่ถือผอบลบความจำ ส่วนสาลิกาเห็นเขาเป็นนักรบทองคำไร้หน้า เธอถอยชนกำแพง หอบจนพูดไม่ออก เขาตวาดชื่อเธอดังครั้งแรก “สาลิกา!” เสียงนั้นตัดภาพลวงได้ชั่วขณะ นางกะพริบตาถี่ก่อนยกมือกดขมับ “ข้ายังอยู่” เขาเองก็ต้องหลับตานับลมหายใจเพื่อกันไม่ให้เงาของบิดากลับมาปักอยู่ตรงหน้าอีก ความมืดใต้ดินที่นี่ไม่ได้หลอกให้กลัวผี หากหลอกให้คนสงสัยคนที่ยืนข้างตัวเอง

เมื่อสุดบันไดเปิดออกสู่โถงกว้าง ทั้งสองหยุดพร้อมกัน แสงตะเกียงส่องไปไม่ถึงปลายห้อง แต่ก็พอเห็นรางเหล็ก คราบเลือดแห้ง และสัญลักษณ์ราชการตามเสาได้ชัดเจน อัคคีสูดลมหายใจที่เหม็นสนิมเข้าเต็มอก แล้วรู้ว่าพวกเขาเพิ่งเดินลงมาถึงท้องของสัตว์ประหลาดตัวจริงเสียที""",
11: """โถงใต้ดินกว้างกว่าที่มนุษย์ควรสร้างเพื่ออะไรก็ตามนอกจากการทำชั่ว เตาหลอมหลายเตาติดไฟสีคล้ำอยู่ไกลๆ รางเหล็กทอดผ่านพื้นหินไปยังแท่นยันต์ที่มีคราบเลือดหนาจนเกือบดำน้ำมัน เสียงโซ่ลากดังเป็นจังหวะชวนขนลุกก้องมาจากด้านใน อัคคีกับสาลิกาหลบอยู่หลังเสา เห็นนักโทษผอมโซหลายคนถูกลากผ่านทีละชุด แต่ละคนมีผ้าปิดตาและยันต์ปิดปากเหมือนกลัวว่าทั้งเสียงและสายตาจะเป็นพยาน “นี่มันไม่ใช่ที่เก็บศพ” สาลิกาพึมพำ “มันคือโรงงาน”

คนงานอาคมคนหนึ่งเปิดประตูเหล็กเตี้ย ปล่อยพลังอาฆาตสีดำพวยพุ่งขึ้นมาจากหลุมด้านใน ก่อนยัดมันเข้าไปในโครงร่างไม้กับเหล็กที่นอนเรียงอยู่บนแท่น ร่างเหล่านั้นกระตุกพร้อมกันเหมือนปลาถูกชักขึ้นบก นักโทษคนหนึ่งกรีดร้องเมื่อเงาดำไหลผ่านแขนตัวเองแล้วถูกดูดเข้าเตาอีกด้าน อัคคีกำด้ามดาบจนเส้นเอ็นตึง เขาเคยสงสัยมานานว่ารัฐใช้สิ่งใดสร้างอาวุธลับ แต่ไม่เคยคิดว่าคำตอบจะออกมาเป็นเนื้อคนและวิญญาณบดรวมกันเช่นนี้ สาลิกาจับแขนเขาไว้แน่นเหมือนอ่านความคิดได้ “ถ้าท่านพุ่งออกไปตอนนี้ เราจะตายหมด” 

เขาฝืนตัวเองถอยครึ่งก้าว แล้วเปลี่ยนไปช่วยปลดโซ่นักโทษที่ถูกทิ้งไว้ท้ายแถวแทน ชายชราคนหนึ่งแทบไม่เชื่อสายตาตัวเองเมื่อเห็นคนในเครื่องแบบมือปราบช่วยตัดเครื่องพันธนาการ “หนีได้หรือยัง” อัคคีถามสั้นๆ ชายคนนั้นส่ายหน้า “ทางออกถูกผนึก...ถ้าเตาไม่ดับ เราก็ออกไม่ได้” คำตอบนั้นทำให้เขาเหลือบไปเห็นผนังอีกด้านซึ่งมีแถวหุ่นพยนต์ยืนคอตกอยู่เป็นสิบ ร่างแต่ละตัวถือดาบแตกต่างกันไป ราวกับรอคำสั่งเดียวก็จะถูกปล่อยออกไปล่ามนุษย์แทนเจ้าของเดิม

เสียงระฆังเตือนดังขึ้นกะทันหันเมื่อคนงานอาคมพบโซ่ที่ถูกตัด ไฟในเตาหลอมปะทุสูงพร้อมกันทั้งห้อง และหุ่นพยนต์แถวหน้าก็เงยศีรษะขึ้นช้าๆ แบบที่สิ่งไม่มีหน้าไม่ควรทำ สาลิกาหันมามองอัคคี ดวงตาเธอไม่ได้ถามว่าควรหนีหรือสู้ เพราะรู้คำตอบแล้ว เขายกดาบขึ้น รับน้ำหนักไว้เต็มมือ ขณะที่ร่างไร้หน้าทั้งแถวเริ่มขยับพร้อมกัน""",
12: """เสียงโลหะกระทบกันในโรงงานผีดังสะท้อนจนหูชา หุ่นพยนต์ตัวแรกพุ่งเข้ามาเร็วผิดร่างไม้ อัคคีรับคมดาบไว้แล้วหมุนตัวตัดข้อศอกมันขาดในจังหวะเดียว แต่ตัวที่สองและสามเข้ามาซ้อนทันทีราวอ่านการเคลื่อนไหวเขาออกหมด เขาถอยหนึ่งก้าว สังเกตเท้าของศัตรู แล้วความเย็นวาบก็ไล่ขึ้นสันหลัง เพราะจังหวะยกไหล่และการกดน้ำหนักนั้นเหมือนกระบวนท่าที่เขาถูกสอนมาตั้งแต่เด็กอย่างไม่มีผิด “เป็นไปไม่ได้” เขาพึมพำ

หุ่นตัวหนึ่งแทงต่ำแล้วเฉือนสูง อัคคีเบี่ยงหลบทันด้วยปฏิกิริยาที่ฝังอยู่ในกระดูก “ท่านรู้ท่านี้” สาลิการ้องเตือนขณะคุมผู้รอดให้ถอยไปทางประตู เขากระแทกตัวเข้าชนหุ่นจนล้ม แล้วเห็นเส้นอาคมสีทองแวบอยู่ในคอของมัน “สายฝึกนี้...” เขายังพูดไม่จบ อีกตัวก็ฟาดดาบลงมาจากด้านหลัง เขารับไว้ได้หวุดหวิด แรงปะทะทำให้เข่าจมลงกับพื้นหิน ราวกับกำลังสู้กับเงาของตัวเองหลายร่างพร้อมกัน ทุกกระบวนท่าที่เขาภูมิใจกลับกลายเป็นหลักฐานว่ามันถูกขโมยไปใช้สร้างปีศาจอย่างไร

สุดท้ายเขาต้องใช้เล่ห์มากกว่าฝีมือ อัคคีล่อให้หุ่นสองตัวแทงสวนกันเอง ก่อนพุ่งเข้าไปตัดแกนยันต์ที่หลังคอของตัวนำ เสียงมันครางต่ำคล้ายคนเจ็บจริงๆ แล้วร่างทั้งร่างก็ทรุดลงแตกเป็นเศษไม้ไหม้กับเหล็กบิดงอ สาลิกาวิ่งเข้ามาทันที “ไป เดี๋ยวทั้งห้องปิดตาย” เขาก้มจะตาม แต่แสงวาบจากซากหุ่นสะดุดตา เศษบางอย่างสีทองติดอยู่ตรงรอยผ่า เขาใช้ปลายมีดเขี่ยออกมา มันคือแผ่นทองโค้งเล็กๆ เหมือนชิ้นส่วนหน้ากากหรือเกราะบางแบบที่ไม่ควรอยู่ในหุ่นทดลองทั่วไป

อัคคีเก็บเศษทองใส่มือไว้แน่นจนขอบคมบาดฝ่ามือ แล้วพาผู้รอดไม่กี่คนวิ่งฝ่าควันออกจากโถง ข้างหลังพวกเขา เสียงหุ่นพยนต์ตัวอื่นยังเริ่มขยับตามมาเหมือนฝูงสัตว์ตื่นกลิ่นเลือด เขาไม่ได้หันกลับไปอีก แต่รู้ดีว่าโรงงานแห่งนี้จะตามเข้ามาอยู่ในหัวเขาไปอีกนาน และเศษทองชิ้นนี้กำลังจะพาเขาไปเจอความจริงที่เลวร้ายกว่าซากศพในตรอกคืนนั้นเสียอีก""",
13: """บ้านพักของเครือข่ายคนความจำพร่าเงียบจนได้ยินเสียงคนทวนชื่อกันจากห้องถัดไป หญิงชราคนหนึ่งกำลังป้อนน้ำให้ชายวัยกลางคนซึ่งเอาแต่พึมพำชื่อภรรยาซ้ำไปมา ทั้งที่นางนั่งอยู่ข้างเขานั่นเอง สาลิกาพาผู้รอดจากโรงงานเข้ามาทีละคน จดสิ่งที่พวกเขายังจำได้ลงบนผ้าขาวแทนกระดาษ เพราะบางคนกลัวตัวหนังสือทางการเสียยิ่งกว่ากลัวผี อัคคียืนอยู่ริมผนัง ไม่ชินกับการอยู่ในที่ที่ความอ่อนแอของผู้คนไม่ได้ถูกซ่อนไว้ด้วยระเบียบหรืออาวุธใดเลย

แม่ครูพวงคำ เจ้าของบ้านพัก เป็นหญิงชราหลังค่อมเล็กน้อย แต่มือยังมั่นคงอย่างคนเย็บแผลคนมาทั้งชีวิต นางมองอัคคีแค่แวบเดียวก็รู้ว่าเคยเป็นคนของรัฐ “ถ้าเอ็งคิดจะมาสั่งคนเจ็บให้เงียบ ที่นี่ไม่มีที่ให้ยืน” นางว่า เขารับคำดื้อๆ “ข้าไม่ได้มาสั่ง” หญิงชราหัวเราะจาง “งั้นก็ดี เพราะคนที่ถูกลบมามากแล้ว บางทีต้องมีคนช่วยจำแทน ไม่ใช่ช่วยลืม” คำพูดนั้นแทงเข้าเป้าพอดีจนเขาเลือกเงียบไว้ดีกว่าเถียง

คืนนั้นสาลิกานั่งอยู่ลำพังกับเศษทองที่เก็บมาจากหุ่นพยนต์ แม่ครูหลับไปแล้ว ผู้รอดหลายคนเริ่มผล็อยเพราะยาสมุนไพร นางแตะเลือดตัวเองลงบนแผ่นทองเพียงนิด ภาพก็แล่นเข้ามาทันที เห็นเงาห้องพิธีกว้างใหญ่ เห็นระฆังเงินเรียงเป็นแถว และเห็นบางอย่างคลุมหน้าด้วยทองครึ่งใบยืนอยู่ในหมอกแดง นางผงะถอย มือเย็นเฉียบ “หน้ากาก...” เสียงหลุดออกมาเบาจนแทบไม่เป็นคำ อัคคีที่เดินเข้ามาพอดีจับไหล่นางไว้ “เห็นอะไร” สาลิกาเงยหน้าขึ้น ดวงตาสั่นแต่ไม่หลบ “ข้าเห็นของที่ทำจากทองชิ้นเดียวกับนี่ และมันไม่ได้อยู่ในหลุมทดลอง มันอยู่ใกล้คนที่สั่งทั้งหมดนี้” 

ด้านนอกบ้านพัก ลมกลางคืนพัดแผ่วพาเสียงเมืองไกลๆ เข้ามาเหมือนไม่มีอะไรเกิดขึ้นในโลก แต่คนในเรือนเล็กนี้ต่างรู้แล้วว่าความพังไม่ได้จำกัดอยู่แค่ชายแดนหรือใต้ดิน มันกำลังคลานเข้าหัวใจเมืองทีละน้อย และเงาของหน้ากากทองคำก็เริ่มชัดเกินจะละเลยได้อีกต่อไป""",
14: """เช้าอีกวัน แม่ครูพวงคำเย็บผ้าขาวผืนใหม่เพิ่มลงบนผนังที่เต็มไปด้วยชื่อผู้สูญหาย นางใช้ด้ายแดงเย็บทีละเข็มเหมือนกลัวว่าถ้ารีบเกินไป ชื่อจะขาดจากโลกจริงๆ สาลิกานั่งจดเศษความทรงจำของผู้รอดอยู่ข้างๆ ส่วนอัคคีช่วยบดสมุนไพรให้คนไข้เงียบๆ ภาพนั้นทำให้แม่ครูเหลือบมองเขาด้วยแววตาใหม่เล็กน้อย “มีดาบอยู่ในมือมาตลอด ไม่คิดว่าจะแยกใบยาเป็น” นางแคะ เขาตอบโดยไม่เงยหน้า “แยกได้แค่ของที่ยังไม่ตาย” หญิงชราหรี่ตา แล้วปล่อยให้ความเงียบทำงานแทนคำปลอบ

พอตกบ่าย คนจากพระนครชั้นนอกก็เริ่มหลบเข้ามามากขึ้น บางคนลืมทางกลับบ้าน บางคนลืมชื่อลูกตัวเองกลางตลาด แม่ครูพวงคำฟังแต่ละเรื่องแล้วสีหน้าเคร่งลงเรื่อยๆ “นี่ไม่ใช่อาการตกค้างเฉพาะราย” นางสรุป “มีใครบางคนกำลังเร่งอาคมให้กินเป็นวงกว้าง” อัคคีเงยขึ้นทันที สาลิกาวางพู่กันช้าๆ “ถ้าเป็นอย่างนั้น เมืองจะเริ่มลืมพร้อมกัน” หญิงชราพยักหน้า “และเมื่อคนลืมพร้อมกัน คนทำก็จะเรียกมันว่าความสงบใหม่” คำพูดนั้นทำให้ทุกคนในห้องเย็นวาบพร้อมกัน

ค่ำลงพร้อมข่าวลือและคำสั่งใหม่ของรัฐ ประกาศหลายฉบับถูกแปะทั่วพระนครให้ประชาชนระวังข่าวเท็จ อย่าพูดถึงคนหาย อย่าพูดถึงเหตุลืมหมู่ เพราะเป็นภัยต่อความเรียบร้อย อัคคีกำกระดาษประกาศยับอยู่ในมือ “ยิ่งห้ามพูด ก็ยิ่งแปลว่ามันจริง” เขาว่า สาลิกามองผ้าชื่อผู้สูญหายที่ไหวเบาๆ ตามลม “คนลืมง่ายเพราะไม่มีหลักยึด หากเราไม่เก็บชื่อไว้ สุดท้ายจะไม่มีใครรู้ด้วยซ้ำว่าถูกขโมยอะไรไป” 

คืนเดียวกันนั้นเอง พวงคำหยิบผ้าผืนหนึ่งยื่นให้อัคคี บนผ้ามีรายชื่อคนหายเขียนแน่นจนแทบไม่มีช่องว่าง “แบกคนเดียวไม่หมดหรอก” นางบอก เขามองผืนนั้นนิ่งๆ ก่อนรับมาโดยไม่พูด ข้างนอก เสียงฆ้องจากเมืองดังมาถึงอย่างห่างๆ ราวกับพระนครกำลังเตรียมพิธีบางอย่างอยู่จริง""",
15: """สาลิกาวางเศษทองลงกลางฝ่ามือแล้วหยดเลือดตัวเองทับอีกครั้ง คราวนี้นางตั้งใจให้เห็นชัดกว่าเดิม เพราะเวลาของพวกเขาเหลือน้อยเกินระวังตัว ภาพที่เปิดออกทำให้ทั้งตัวเย็นวาบ นางเห็นห้องพิธีกว้างเหมือนท้องวังใต้ดิน เส้นยันต์แดงพาดไปทั่วพื้น และเหนือแท่นกลางห้องมีหน้ากากทองคำครึ่งใบแขวนอยู่ราวกำลังรอเจ้าของ หลวงวิจิตรยืนอยู่ใต้หน้ากากนั้น มือประคองขันอาคมด้วยสีหน้าเมตตาแบบคนที่ไม่เชื่อว่าตัวเองทำบาป สาลิกาสะบัดมือหนีภาพ หอบจนไหล่สั่น

“ท่านเห็นใคร” อัคคีถามทันที นางตอบช้าๆ “ข้าเห็นเขา...และเห็นพิธีที่ยังไม่เริ่มเต็มรูป” เธอเงยหน้าขึ้น สบตาเขาตรงๆ “เศษทองนี่มาจากของเดียวกับหน้ากากในห้องนั้น” คำพูดทำให้อัคคีเหมือนถูกลากกลับไปหาเงาชายในฝนอีกครั้ง แต่เขาไม่ทันถามต่อ เพราะเสียงโกลาหลดังจากตลาดชั้นนอก ผู้คนหลายสิบคนหยุดกลางการกระทำพร้อมกันจริงๆ แม่ค้าที่กำลังตักแกงค้างช้อน เด็กที่กำลังหัวเราะหยุดไปเฉยๆ ก่อนร้องไห้เมื่อจำคำต่อไปไม่ได้

อัคคีกับสาลิการีบออกไปถึงขอบตลาด เห็นคนยืนมึนงงเหมือนถูกดึงคำสุดท้ายออกจากหัวพร้อมกันทั้งแถว ชายคนหนึ่งจับแขนภรรยาแล้วถามซ้ำๆ ว่า “เรากลับบ้านทางไหน” ทั้งที่ร้านตัวเองอยู่ห่างไปแค่ไม่กี่ก้าว สาลิกาหน้าซีด “มันเริ่มแล้ว แค่ยังไม่เต็มแรง” อัคคีช่วยประคองเด็กหญิงคนหนึ่งที่ทรุดร้องหาแม่ ทั้งที่แม่ยืนกอดอยู่ตรงหน้า เขาไม่เคยเห็นภัยใดกินคนได้มากขนาดนี้โดยไม่ต้องมีเลือดตกแม้หยดเดียว

เมื่ออาการค่อยซา ผู้คนก็เหลือเพียงความหวาดกลัวกับช่องว่างแปลกๆ ในหัว อัคคียืนมองพระนครชั้นนอกที่เหมือนเดิมแต่ไม่เหมือนเดิมแล้วแม้แต่น้อย เขาหันกลับมาหาสาลิกา “ถ้าปล่อยต่อไป เมืองทั้งเมืองจะเป็นแบบนี้” นางพยักหน้าช้าๆ “และคนที่ไม่ลืมจะถูกเรียกว่าเป็นต้นเหตุ” ลมเย็นยามเย็นพัดผ่านตลาดที่เพิ่งเงียบลงราวสนามศพ ทั้งคู่รู้พร้อมกันว่าจากนี้เรื่องไม่ได้เป็นเพียงการตามหารอยศพหรือห้องลับอีกแล้ว แต่มันเป็นการแข่งขันกับเวลาของทั้งเมือง""",
16: """วันต่อมา พระนครทั้งชั้นนอกสั่นด้วยความพร่าพร้อมกันเป็นระลอก คนขายของหยุดกลางประโยค เด็กหลงแม่ทั้งที่ยืนจับมือกันอยู่ ข้าราชการหนุ่มคนหนึ่งยืนร้องไห้หน้าที่ทำการเพราะจำชื่อตัวเองไม่ได้ชั่วครู่ อัคคีกับสาลิกาเดินฝ่าฝูงชนไปตามถนนอย่างระวัง ไม่ใช่กลัวถูกมองเห็นอย่างเดียว แต่กลัวเห็นผู้คนแตกเป็นชิ้นด้วยความลืมต่อหน้ามากกว่า “มันแค่ทดลอง” สาลิกาบอกเมื่อเห็นเส้นอาคมจางๆ ลอยอยู่เหนือหลังคาบางแนว “ถ้าเป็นพิธีเต็ม เราอาจไม่เหลือใครสักคนที่จำได้ว่าตัวเองเคยสูญเสียอะไรไป”

คำประกาศของหลวงวิจิตรถูกอ่านจากศาลาเมืองในเวลาเดียวกัน เสียงขานดังชัดเหนือความโกลาหล เรียกให้ประชาชนอย่าตื่นตระหนก และประกาศจับขุนอัคคีในข้อหาปล่อยข่าวบ่อนทำลายความสงบ ผู้คนหันมองกัน แต่หลายคนจำหน้าคนในประกาศไม่ได้เสียด้วยซ้ำ จึงเกิดแต่ความสับสนงุนงง อัคคีดึงผ้าคลุมหน้าลงต่ำขึ้นอีก “เขาจะให้ทั้งเมืองลืมว่ากำลังถูกทำอะไร แล้วเรียกมันว่าการคุ้มครอง” สาลิกาหันมามอง “ท่านยังจะเก็บหลักฐานไว้ใช้ขึ้นศาลอีกหรือ” น้ำเสียงนางไม่ได้ประชด แค่ถามว่าถึงเวลาทิ้งวิธีเดิมหรือยัง

พวกเขาหลบกลับฐานก่อนค่ำพร้อมข่าวร้ายรอบด้าน ที่พักปลอดภัยหลายจุดเริ่มถูกค้น ผู้คนที่ยังจำได้ถูกจับตาเป็นพิเศษ แม่ครูพวงคำฟังรายงานแล้วเพียงพ่นลมหายใจ “ช้ากว่านี้ไม่ได้แล้ว” อัคคีมองผนังชื่อผู้สูญหาย เห็นว่ามีบางชื่อถูกคนในบ้านทวนไว้ซ้ำๆ เพราะกลัวพรุ่งนี้จะจำไม่ได้ เขาเคยคิดว่าตนแค่ต้องลากความจริงออกมาต่อหน้าผู้มีอำนาจ แต่ตอนนี้เขารู้แล้วว่าหากไม่ทุบระบบทั้งชุด เมืองจะถูกฆ่าทั้งเป็นด้วยความเรียบร้อยของมันเอง

คืนนั้นเขาจึงพูดออกมาตรงๆ เป็นครั้งแรก “ข้าจะไม่หยุดที่คดีนี้แล้ว” สาลิกาวางผ้าชุบน้ำลงบนโต๊ะ มองเขานิ่ง “ดี เพราะเมืองทั้งเมืองก็กำลังรอให้มีใครสักคนเลิกคิดว่ามันเป็นแค่คดีเดียว” นอกบ้านพัก เสียงประกาศล่าหัวยังดังไปไกลตามถนน และชื่อของอัคคีก็เริ่มถูกปล่อยออกไปในฐานะศัตรูของความสงบอย่างเป็นทางการ""",
17: """หมื่นชยุตตามรอยเหมือนสุนัขศึกที่ไม่เคยหลับ เขาไม่ได้ใช้เสียงดัง ไม่ใช้คบไฟมาก แต่ที่พักปลอดภัยแต่ละแห่งกลับถูกเจาะพบทีละจุดอย่างแม่นยำ สามคืนติดกันอัคคีกับสาลิกาต้องย้ายคนเจ็บและเด็กหนีจากบ้านหนึ่งไปอีกบ้านหนึ่ง จนแม้คนแข็งอย่างอัคคียังเริ่มเห็นความเหนื่อยปักอยู่ในสายตาผู้รอดทุกคน ชยุตคือคนที่เคยฝึกภาคสนามด้วยกัน เขารู้วิธีคิดของอัคคีพอๆ กับที่อัคคีรู้วิธีเข้าล้อมของเขา

คืนหนึ่ง ขณะพวกเขาพักหายใจในยุ้งข้าวร้าง ชยุตก็นำกำลังมาถึงเร็วกว่าที่ควร เสียงถุงมือหนังกระทบด้ามดาบของเขาดังเป็นจังหวะสม่ำเสมอ “แกยังคิดว่าการหนีครั้งนี้จะช่วยใครได้จริงหรือ” เขาเรียกจากนอกกำแพง อัคคีออกไปยืนในเงามืดอีกฝั่งหนึ่ง “ช่วยได้มากกว่าการรับคำสั่งจนคนทั้งเมืองตาบอด” ชยุตเงียบไปนิดหนึ่งก่อนตอบ “ถ้าระเบียบพัง จะมีคนตายมากกว่านี้” “ระเบียบของพวกแกกำลังฆ่าคนอยู่แล้ว” ประโยคสั้นนั้นทำให้ความเป็นเพื่อนร่วมทัพในอดีตเหลือเพียงเถ้าบางๆ

พวกเขาไม่ปะทะกันตรงหน้าในคืนนั้น เพราะอัคคียังต้องถ่วงเวลาให้คนข้างในหนี แต่พอรุ่งสาง ข่าวก็มาถึงว่าจุดพักอีกแห่งถูกตีแตก ผู้รอดบางส่วนหาย บางส่วนถูกจับ และบางส่วนหนีแบบไร้ทิศ อัคคีมองแผนที่หยาบบนพื้นแล้วรู้สึกว่าพื้นที่ปลอดภัยของพวกตนถูกกัดกินทีละคำเหมือนเนื้อสด เขาไม่ได้กลัวการไล่ล่าเท่ากลัวว่าศัตรูรู้มากเกินควรรู้ 

สาลิกาเป็นคนพูดสิ่งนั้นออกมาก่อน “มีคนบอกทางให้เขา” นางไม่ต้องขึ้นเสียง ทุกคนในห้องก็เงียบลงพร้อมกัน แม่ครูพวงคำพับผ้าที่เขียนชื่อค้างไว้ช้าๆ ขณะที่อัคคีรู้ว่าคำว่า ‘คนทรยศ’ หนักหนากว่าดาบใดในช่วงเวลานี้ เพราะมันหมายความว่าศัตรูไม่ได้แค่ล้อมจากภายนอก แต่เริ่มซึมอยู่ในที่พักพิงเดียวกับพวกเขาแล้ว""",
18: """ตอนเช้า ชื่อของขุนอัคคีถูกอ่านออกจากประกาศรัฐทุกหัวถนนด้วยถ้อยคำเดียวกับที่เคยใช้กับอาชญากรและคนปลุกปั่น ผู้คนบางส่วนหันมองอย่างสับสน บางส่วนทำหน้าโล่งเพราะในหัวไม่มีข้อมูลพอจะกลัวใครจริงจังแล้ว อัคคีนั่งเงียบอยู่ในเรือเล็กริมคลองร้าง ฟังชื่อตัวเองถูกตีตราจากปากคนอื่นแล้วไม่รู้สึกอะไรเท่าความว่าง สาลิกานั่งตรงข้าม “ถ้าท่านเริ่มคิดว่ามันสายเกินไป ข้าจะด่า” นางพูด เขาเงยตาขึ้น “ข้ายังไม่คิด” “ดี” นางตอบ “เพราะข้าเองก็ยังไม่ยอมตายให้เขาง่ายๆ” 

เย็นนั้นหมื่นชยุตเกือบเข้าถึงตัวสาลิกาจริงๆ ระหว่างย้ายคนเจ็บผ่านตรอกแคบ เขาพุ่งออกมาจากหลังเกวียนพร้อมหน่วยล่ากลุ่มเล็ก อัคคีรับไว้ทัน แต่ชยุตจงใจหลอกให้เขาตามดาบ ก่อนส่งคนอีกสองคนอ้อมไปทางหลัง “เขาเอานางไปเป็นกุญแจพิธี” สาลิกาเตือนพร้อมปัดมีดสั้นออกจากตัวเอง เธอสู้ไม่เก่งเท่าอัคคี ทว่าไม่เคยยอมเป็นภาระเงียบๆ อย่างที่ศัตรูหวัง ชยุตเห็นดังนั้นจึงถอยกลับทั้งที่ยังไม่ชนะ เพียงทิ้งคำไว้ว่า “ข้าจะกลับมา แล้วครั้งหน้าแกจะกันทุกคนไม่ทัน” 

คำขู่นั้นเป็นจริงเร็วกว่าคิด เพราะเมื่อตกดึก ที่พักหลักถูกค้นเจอแบบแม่นยำเกินบังเอิญ ประตูหลังที่มีแต่คนในรู้กลับถูกล้อมก่อนเป็นจุดแรก อัคคีกระชากผนังไม้เปิดทางหนีสำรองให้ผู้รอด แต่ในใจเขาเย็นวาบลงไปถึงปลายเท้า ยิ่งแผนลับถูกอ่านออกทีละชั้น ก็ยิ่งชัดว่าคนทรยศไม่ได้ฟังผ่านๆ หากยืนอยู่กลางวงสนทนาของพวกเขาจริงๆ

สาลิกายืนหอบอยู่ข้างบันไดมืด มองเปลวตะเกียงที่สั่นจากแรงคนกระทบประตู “คืนนี้จะจบไม่สวย” นางว่า อัคคีหันมามองโดยไม่เสียเวลาเถียง “ข้าจะพาเจ้าออกไป” สาลิกาส่ายหน้าเบาๆ “ท่านคงช่วยทุกคนไม่ได้พร้อมกันแล้ว” ประโยคนั้นทำให้อกเขาหน่วงอย่างที่ไม่อยากยอมรับ เพราะเขารู้ดีว่าเธอพูดถูก""",
19: """รุ่งเช้าหลังการไล่ล่าที่แทบไม่ได้นอน ผู้รอดในที่พักชั่วคราวริมคลองร้างช่วยกันเขียนชื่อผู้หายลงบนผ้าคนละผืน มือหลายคู่สั่นเพราะอดนอนและกลัว แต่ยังฝืนขีดตัวอักษรต่อไปเหมือนกำลังต้านอะไรสักอย่างที่ใหญ่เกินตัว อัคคีนั่งมองอยู่พักหนึ่งก่อนหยิบพู่กันขึ้นเอง เขียนชื่อที่เขายังจำได้ลงข้างชื่อของคนอื่น ความรู้สึกแปลกประหลาดแล่นผ่านอก เพราะนี่เป็นครั้งแรกที่เขาไม่แบกหลักฐานไว้คนเดียวในเงามืด แต่เอามันวางต่อหน้าหลายมือหลายตาอย่างตั้งใจ

แม่ครูพวงคำมองเขาแล้วพูด “ความจำก็เหมือนผ้า ขาดแล้วเย็บได้ แต่รอยเย็บจะอยู่ไปตลอด” อัคคีตอบโดยไม่หยุดเขียน “ถ้าผ้าทั้งผืนถูกเผาเล่า” หญิงชรายักไหล่ “งั้นก็ต้องช่วยกันเก็บขี้เถ้าไว้ ยังดีกว่าทำเหมือนไม่เคยมีผืนนั้น” สาลิกานั่งอยู่ไม่ไกล ฟังสองคนเถียงกันเบาๆ แล้วเผลอยิ้ม เป็นรอยยิ้มอ่อนเพลียแต่จริงกว่าหลายวันที่ผ่านมา ผู้รอดบางคนเริ่มเอ่ยชื่อญาติที่หายไปออกมาเสียงดังขึ้น ราวการได้ยินคนอื่นจำร่วมกันช่วยค้ำหัวใจตัวเองไว้

ช่วงบ่าย อัคคีเรียกประชุมวงเล็ก เขาเคยชินกับการรับแผนจากเบื้องบนแล้วทำให้สำเร็จลำพัง แต่คราวนี้ต้องยอมเปิดทุกอย่างที่มี ทั้งเส้นทางลับ เศษทอง บันทึกลับ และข้อมูลจากโรงงานผี “ถ้าเราจะบุกหอจดหมายเหตุ เราต้องไปด้วยข้อมูลของทุกคน ไม่ใช่ของข้าคนเดียว” คำพูดนั้นทำให้หลายคนมองเขาใหม่ เพราะสำหรับคนที่เคยพูดแต่คำสั่ง การยอมแบ่งภาระคือการเปิดเนื้อส่วนลึกที่สุดออกมาอย่างหนึ่ง แม่ครูพวงคำจึงเพียงพยักหน้า ไม่พูดซ้ำให้เขาอาย

พอตกค่ำ ผ้ารายชื่อหลายผืนถูกเย็บต่อกันเป็นแถวยาว อัคคีจับมองอยู่นานก่อนพูดกับสาลิกา “ข้าเพิ่งรู้ว่าการจำคนเดียวหนักกว่าการสู้ทั้งคืนเสียอีก” นางตอบเบาๆ “ข้าบอกท่านตั้งแต่แรกแล้วว่าความจริงต้องมีคนช่วยถือ” ข้างนอก ลมคลองพัดเย็น แต่มันไม่ได้หนาวเท่าความรู้ว่าพวกเขาเหลือเวลาไม่มากก่อนพิธีใหญ่จะเริ่มจริง""",
20: """เส้นทางลับเข้าสู่หอจดหมายเหตุถูกประกอบขึ้นจากเศษข้อมูลที่ไม่มีชิ้นใดสมบูรณ์ ชายชราผู้รอดจากโรงงานจำรางเหล็กใต้ดินได้ หญิงอีกคนหนึ่งจำกลิ่นสมุนไพรในห้องผนึกได้ มะลิจำได้ว่าทหารที่หนองชันพูดชื่อประตูด้านเหนือหลุดปากระหว่างทะเลาะกัน สาลิกานำทั้งหมดมาปะลงบนผ้าแทนแผนที่ ส่วนอัคคีค่อยๆ เห็นภาพทางเดินที่ไม่เคยมีในเอกสารทางการโผล่ขึ้นจากความทรงจำแตกๆ ของหลายคน “นี่ไม่ใช่แผนของข้า” เขาพูดเมื่อมองเส้นสุดท้ายที่ลากเสร็จ “มันเป็นแผนของคนที่เขาพยายามลบ” 

การแบ่งหน้าที่จึงเริ่มขึ้นอย่างที่เขาไม่เคยทำมาก่อน คนเฝ้าทาง คนลำเลียงหลักฐาน คนดูเด็ก คนเตรียมยันต์ต้านลืม ทุกบทมีความเสี่ยงทั้งนั้น อัคคีลังเลอยู่พักหนึ่งก่อนบอกให้ผู้รอดบางคนถอย แต่แม่ครูพวงคำสวนกลับทันที “เอ็งไม่ใช่เจ้าชีวิตใคร เรารู้ว่ากำลังเลือกอะไร” เขาจึงเงียบแล้วพยักหน้า สาลิกามองอยู่เงียบๆ ก่อนพูดกับเขาเบาๆ “ในที่สุดท่านก็เลิกคิดว่าการปกป้องคนอื่นต้องแปลว่าไม่ให้เขาเลือก” ประโยคนั้นทั้งจริงและเจ็บพอให้เขาไม่หาข้อเถียง

ทุกคนยุ่งอยู่กับการเตรียมทางหนีและเครื่องมือ จนไม่มีใครสังเกตชายคนหนึ่งที่ขอตัวออกไปตักน้ำช้ากว่าปกติ เขายืนอยู่นอกเรือนนานกว่าที่จำเป็น แล้วแอบชะโงกฟังเสียงสนทนาภายในผ่านผนังไม้บางๆ ข้อมูลเรื่องเวลาบุก ทางเข้าด้านใต้ และตำแหน่งคนเฝ้า ถูกดูดเข้าไปทีละคำอย่างเงียบเชียบ ข้างใน อัคคีเพิ่งพูดจบว่า “ถ้าเราไปไม่ถึงสาลิกาก่อนพิธีเริ่ม ทุกอย่างจะสายเกินไป” ไม่มีใครรู้ว่าประโยคนั้นมีคนส่งต่อให้ศัตรูไปแล้ว

ดึกมากแล้วเมื่อวงประชุมยุติ สาลิกาเก็บผ้าแผนที่เข้าห่อผ้าดำ อัคคีนั่งอยู่ข้างประตู ฟังความเงียบรอบบ้านอย่างคนไม่ยอมหลับเพราะสัญชาตญาณยังร้องเตือน เขาไม่รู้ว่าความผิดปกติอยู่ตรงไหน แต่ความสงบของคืนนี้เรียบเกินไปจนชวนให้กลัว ยิ่งเรียบเท่าไร เขาก็ยิ่งนึกถึงรอยยิ้มบางของหลวงวิจิตรมากขึ้นเท่านั้น""",
21: """ตะเกียงในที่พักดับลงทีละดวงเหมือนบ้านทั้งหลังถูกลบชื่อออกจากโลก เริ่มจากห้องครัว ต่อด้วยทางเดิน แล้วสุดท้ายก็ถึงห้องประชุมกลาง เสียงเอะอะดังขึ้นพร้อมกันจากหลายมุม อัคคีชักดาบในความมืดเกือบพร้อมกับที่บานประตูหน้าถูกกระแทกแตก คนของรัฐทะลักเข้ามารวดเร็วผิดกับการบุกค้นทั่วไป ราวรู้ตำแหน่งห้องและทางหนีทุกจุดล่วงหน้าแล้ว “พวกมันรู้หมด!” ใครคนหนึ่งตะโกน สาลิกาคว้าห่อผ้าแผนที่เข้าหาตัว ขณะอัคคีฟันเปิดทางให้ผู้รอดถอยไปหลังบ้าน

คนทรยศถูกเปิดเผยในเสี้ยววินาทีสั้นๆ เมื่อชายผู้หนึ่งวิ่งไปยังประตูที่ควรผนึกจากข้างในแล้วตะโกนเรียกหน่วยล่าจากนอกบ้าน อัคคีเห็นแวบเดียวก็จำได้ว่าเป็นคนที่ร่วมประชุมเมื่อคืน เขาพุ่งไปถึงก่อนอีกฝ่ายจะถอยพ้นธรณี แต่หมื่นชยุตสอดตัวเข้ามากันไว้พอดี ดาบของอดีตสหายปะทะกันกลางแสงไฟไหม้ลุก “แกช้าไปก้าวเดียว” ชยุตว่า อัคคีตอบด้วยแรงฟันที่หนักกว่าเดิม “ข้าช้าเรื่องเชื่อคนผิดมานานแล้ว” 

ระหว่างที่เขาถูกดึงไว้กับชยุต สาลิกาก็มองเห็นชัดว่าคนของรัฐกำลังอ้อมเข้าทางที่ผู้รอดเด็กกับคนเจ็บหลบอยู่ หากปล่อยให้อัคคีสู้ต่อ เขาจะต้องหันกลับไปช่วยหลายทางพร้อมกันและพลาดหมดทุกทาง นางจึงตัดสินใจเร็วอย่างคนที่รู้อยู่แล้วว่าความเจ็บแบบไหนคุ้ม “อัคคี!” นางเรียกชื่อเขาเต็มเสียงเป็นครั้งไม่บ่อย “ข้าจะดึงพวกมันไปทางถนน ท่านพาคนที่เหลือออกหลังบ้าน” เขาหันขวับ “ไม่” แต่สาลิกาไม่รอให้เขาสั่งซ้ำ นางคว้าตะเกียงขว้างใส่ม่านไม้จนไฟลุก แล้ววิ่งตัดออกไปอีกทางพร้อมเสียงรองเท้าตามไล่ของศัตรู

เสี้ยวหน้าที่นางหันกลับมามอง มีทั้งความกลัวและความตั้งใจปนกันอย่างแยกไม่ออก “ถ้าท่านรอด อย่าปล่อยให้คืนนี้หายไป” นางพูด แล้วก็หายเข้าไปในควันกับเสียงคนไล่ล่า อัคคีรู้ในวินาทีนั้นเองว่าเธอไม่ได้แค่หนี เธอกำลังเลือกเป็นเหยื่อล่อแทนเขา และการเลือกนั้นจะฉีกเขาออกเป็นสองทางไม่ว่าจะตัดสินใจอย่างไรต่อก็ตาม""",
22: """อัคคีฝ่าแนวล้อมออกสู่ถนนส่งตัวเชลยได้ในที่สุด แต่ช้าไปกว่าที่ต้องการเพียงนิดเดียว และบางครั้งนิดเดียวก็พอจะพังชีวิตทั้งช่วง เขาเห็นสาลิกาถูกจับขึ้นรถม้ากรงเหล็ก มือสองข้างถูกตรึงด้วยสายอาคมสีแดง ชยุตยืนคุมอยู่ข้างล้อรถพร้อมทหารอีกแถวหนึ่ง ฝนเริ่มตกปรอยเหนือหลังคาเมือง น้ำหยดจากเส้นผมของสาลิกาลงข้างแก้มเหมือนน้ำตาที่เจ้าตัวไม่ยอมปล่อย “ปล่อยนาง” อัคคีพูดไม่ดัง แต่คมพอจะทำให้คนหลายคนชะงัก

ชยุตส่ายหน้า “คราวนี้แกเลือกไม่ทันแล้ว” เขาตอบ อัคคีพุ่งเข้าไป ดาบของเขาฟันผ่านทหารสองคนแรก แต่คนที่เหลือขยับปิดเป็นวงทันทีเหมือนซ้อมมาแล้ว สาลิกาเกาะขอบกรงแน่น เลือดซึมจากข้อมือใต้สายอาคม “อย่ามัวแต่ช่วยข้า!” นางตะโกนแข่งเสียงม้า “พิธีอยู่ในหอจดหมายเหตุ เขาเริ่มภายในไม่กี่วัน!” คำบอกนั้นแทงเข้าเขาได้แรงยิ่งกว่าหอกใด เพราะมันหมายความว่าแม้ถูกจับ นางยังต้องคอยผลักเรื่องต่อแทนความกลัวของตัวเองอยู่ดี

อัคคีเกือบถึงกรงอยู่แล้วเมื่อชยุตปักดาบขวางกลางทาง แรงปะทะทำให้เขาถูกผลักถอยสองก้าว รถเริ่มเคลื่อน ม้ากระชากออกทีละช่วง สาลิกาเอื้อมมือทั้งที่ข้อมือยังถูกตรึง “อย่าตามข้ามาตาบอดๆ ฟังข้า!” อัคคีไม่แน่ใจว่าเขาได้ยินคำไหนก่อน ระหว่างเสียงเธอหรือเสียงเลือดในหูตัวเอง เขาฟันทิ้งอีกครั้งแต่พลาดเพียงปลายเหล็กโดนกรง เกิดเสียงดังแหลมบาดประสาท รถค่อยๆ ห่างออกไปทีละคืบ ในระยะที่ยังเห็นสายตากันได้ เขารู้ว่านี่คือวินาทีที่เขาเอื้อมไม่ถึงจริงๆ

สาลิกาถูกพาเข้าเขตหอชั้นในก่อนฟ้าสาง ผ่านประตูเหล็กและห้องผนึกที่เย็นจนผิวแสบ ในช่วงที่คนคุมเผลอ นางเงยหน้าขึ้นจากความมึนงงแล้วเห็นมันแขวนอยู่เหนือแท่นกลางห้อง—หน้ากากทองคำครึ่งใบส่องแสงทึบเหมือนยังมีความทรงจำติดค้างอยู่ข้างใน เลือดในกายสาลิกาเย็นลงทันที เพราะนางรู้แล้วว่าภาพจากเศษทองไม่ใช่คำเตือนอีกต่อไป มันคือสถานที่จริงที่นางถูกพามาอยู่กลางวงด้วยตัวเอง""",
23: """เส้นยันต์บนพื้นห้องผนึกเย็นจนแสบผิวเท้า สาลิกาถูกจับนั่งกลางวงอาคมโดยมีสายแดงรัดข้อมือกับข้อเท้าไว้แน่น ระฆังเงินหลายใบแขวนเรียงเหนือศีรษะ รอเพียงมือใครสักคนสั่นมันครั้งเดียวให้เสียงลืมวิ่งไปทั้งเมือง หลวงวิจิตรยืนมองอยู่ไม่ไกล สีหน้าเรียบสะอาดเหมือนกำลังเตรียมพิธีมงคลมากกว่าจะสังเวยมนุษย์ “เจ้าเป็นเพียงดวงตา” เขาพูดอ่อนโยน “อย่าทำให้ตัวเองลำบากเกินจำเป็น” สาลิกายิ้มแห้ง “คนที่ชอบเรียกคนอื่นว่าเครื่องมือ มักกลัววันที่เครื่องมือนั้นมองกลับที่สุด” ชายชราเพียงยิ้มบางเหมือนสงสารความดื้อของเด็กคนหนึ่ง

ทุกครั้งที่อาคมเริ่มไหล นางจะเห็นภาพพร่าของคนทั้งเมืองเหมือนผืนผ้าใหญ่ถูกดึงเส้นด้ายออกทีละเส้น ระหว่างความเจ็บนั้นเอง ประตูด้านข้างเปิดให้ร่างหนึ่งเดินเข้ามา นักรบทองคำสวมหน้ากากครึ่งใบและถือดาบนิ่งสนิท ทว่าชั่วเสี้ยวที่นางเผลอพึมพำชื่อ “อัคคี” ไปเบาๆ มือของมันกลับกระตุกน้อยมากแต่ชัดพอให้สังเกต หลวงวิจิตรหันมามองทันที สาลิกาเลยก้มหน้าซ่อนสีหน้าไว้ แต่นาทีนั้นก็พอให้ความกลัวเปลี่ยนรูป กลายเป็นความจริงที่หนักยิ่งกว่าเดิม—สิ่งมีชีวิตตรงหน้าไม่ได้เป็นเพียงอาวุธ มันยังเหลือบางอย่างที่ได้ยินชื่อเขาอยู่ข้างใน

อีกด้านหนึ่งของเมือง อัคคีกำลังรวบรวมคนที่ยังพอสู้ได้อยู่ในเงากำแพงหอ เขารู้จากคำของสาลิกาแล้วว่าพิธีกำลังเริ่ม แต่น้ำเสียงสุดท้ายของนางยังติดอยู่ในหัวราวตะขอ เขากระชับห่อหลักฐานกับเศษทองไว้ที่อก แม่ครูพวงคำมองเขาก่อนออกเดิน “ถ้าช่วยนางไม่ได้ อย่างน้อยอย่าให้คนทั้งเมืองตายฟรี” เขาพยักหน้าโดยไม่พูด เพราะถ้าเปิดปากตอนนั้น เขาไม่แน่ใจว่าคำไหนจะหลุดออกมาก่อน ระหว่างแผนบุกกับชื่อของสาลิกา

เมื่อระฆังพิธีดังครั้งแรกจากใต้หอ เสียงมันบางและไกล แต่สั่นเข้ามาถึงกระดูกของทั้งผู้ถูกจับและผู้กำลังบุก สาลิกาหลับตาแน่น ไม่ใช่เพราะยอมแพ้ แต่เพราะต้องคุมไม่ให้ตัวเองกรีดร้องจากแรงอาคมที่พยายามเปิดร่างเธอเป็นประตู ขณะเดียวกัน อัคคีเงยหน้ามองหอมืดสูงเหนือกำแพง แล้วก้าวเข้าสู่ทางที่ไม่มีสิทธิช้าอีกแล้ว""",
24: """ทางลับใต้กำแพงหอจดหมายเหตุชื้นจนพื้นลื่น อัคคีนำหน้าคนเพียงไม่กี่คนผ่านอุโมงค์แคบที่ผู้รอดช่วยต่อชิ้นส่วนข้อมูลกันขึ้นมา แสงตะเกียงถูกบังไว้ด้วยผ้าดำเพื่อไม่ให้เล็ดลอด เขาพกหลักฐานทุกชิ้นที่สำคัญที่สุดไว้กับตัว—สมุดปกดำ เศษทอง รอยจดบันทึกเรื่องโรงงานผี และชื่อของผู้หายบางส่วนที่พวงคำยัดใส่มือก่อนออกมา “อย่าเข้าไปเหมือนมีแค่ดาบ” นางบอก “เอาคนที่หายไปทั้งหมดเข้าไปด้วย” เขาเพิ่งเข้าใจว่าคำนี้หมายถึงอะไร เมื่ออกเสื้อหนักจนแทบกดไหล่ให้ตกทุกครั้งที่หายใจ

อุโมงค์สิ้นสุดที่ห้องเก็บเอกสารเก่าชั้นล่างซึ่งไร้คนเฝ้าเพราะทุกกำลังถูกดึงไปดูพิธี เสียงระฆังครั้งแรกสั่นมาจากข้างบนชัดเจนกว่าเดิมจนฝุ่นจากคานไม้ร่วงพราวลงมา คนที่มาด้วยหน้าซีดกันถ้วนหน้า “ยังถอยทัน” หนึ่งในนั้นกระซิบ อัคคีส่ายหน้า “เราเลยจุดนั้นมาตั้งแต่หนองชันแล้ว” เขาเปิดบานหินแคบอีกชั้นตามรอยอักขระที่จำจากโรงงานผี และเมื่อมันเลื่อนออก ลมเย็นจัดที่มีกลิ่นหมึกเก่ากับเลือดใหม่ก็พุ่งใส่หน้าทันที

เบื้องหน้าคือบันไดอักขระที่ทอดขึ้นสูงในแสงขาวซีด เส้นยันต์ใต้พื้นเรืองเป็นช่วงๆ เหมือนมีใครกำลังหายใจอยู่ทั้งโครงสร้าง สองข้างทางเป็นชั้นเก็บคัมภีร์สูงเสียดเพดานจนดูเหมือนสุสานแนวตั้งมากกว่าหอเก็บความรู้ “ที่เก็บความจริง...” อัคคีพูดกับตัวเอง “กลับถูกใช้ฆ่าความจริง” คนข้างหลังไม่มีใครตอบ เพราะแต่ละคนต่างรู้แล้วว่าเบื้องบนมีอะไรคอยอยู่ เขาสั่งให้สองคนแยกไปปล่อยหลักฐานตามจุดที่เตรียมไว้ ส่วนตนจะขึ้นไปให้ถึงห้องพิธีก่อนพิธีสมบูรณ์

เสียงระฆังครั้งที่สองดังขึ้นตอนเท้าเขาแตะขั้นแรก พื้นบันไดสั่นเหมือนตอบรับ เขาเงยหน้ามองความสูงมืดตรงหน้า เห็นเงาหน่วยอาคมรักษาการณ์เริ่มขยับลงมาเป็นชั้นๆ และรู้ว่าจากนี้ไป ทุกก้าวจะต้องแลกด้วยเลือดจริง ไม่ใช่แค่ความลับหรือคำโกหกอีกต่อไป""",
25: """อักขระใต้ฝ่าเท้าเรืองขาวทุกครั้งที่อัคคีก้าวขึ้นบันได เสียงรองเท้าของหน่วยอาคมรักษาการณ์ดังลงมาประสานกันเหมือนกลไกเดียว มากกว่าทหารหลายคน เขาปะทะชุดแรกกลางขั้นบันไดแคบ ดาบฟันสวนกับหอกยันต์จนเกิดแสงวาบสะท้อนชั้นคัมภีร์สูงตระหง่านรอบด้าน เลือดสาดลงบนพื้นขาวแล้วดูดำสนิท ราวกับสถานที่นี้จงใจปฏิเสธสีจริงของมนุษย์ทุกคนที่ยืนอยู่ในนั้น “หยุดอยู่แค่นี้ ขุนอัคคี” ผู้รักษาการณ์คนหนึ่งตะโกน “ยังกลับใจได้” เขาฟันตอบแทนคำพูด เพราะรู้ดีว่าคำว่า ‘กลับใจ’ ในหอนี้แปลว่าให้กลับไปเป็นมีดของใครอีกครั้ง

การต่อสู้บนบันไดต่างจากสนามเปิด ทุกจังหวะผิดพลาดหมายถึงตกลงไปตายหรือถูกอาคมทับทันที อัคคีใช้ความรู้ทางดาบผสมกับการอ่านพื้นที่อย่างคนเคยไล่ล่าในตรอกแคบ เขาเตะศพที่ล้มให้กลิ้งขวางจังหวะคนตามหลัง ก่อนฉวยหอกยันต์มาปักใส่ผนังให้เส้นอาคมลัดวงจร พื้นที่ครึ่งช่วงบันไดระเบิดแสงขาวชั่วขณะ เปิดทางให้เขาพุ่งขึ้นอีกหลายขั้น แต่ยิ่งสูง เสียงระฆังจากห้องพิธีก็ยิ่งดังในอกชัดขึ้นเรื่อยๆ เหมือนเตือนว่าเวลาของสาลิกากำลังรั่วออกทุกลมหายใจ

เมื่อถึงชั้นพักใหญ่ เขาพบหน่วยอาคมอีกชุดคุมประตูชั้นในไว้ แนวตั้งมั่นราวกำแพงมีชีวิต อัคคีไม่ชะลอ เขาใช้คมดาบฉีกช่องแรกได้ก็จริง แต่ก็แลกกับแผลยาวที่สีข้าง เลือดอุ่นไหลลงเอวอย่างรวดเร็ว คนหนึ่งพยายามร่ายคาถาพันธนาการใส่ เขากลับเอื้อมมือเปื้อนเลือดจับเส้นยันต์นั้นฉุดให้เบี่ยงไปโดนเจ้าของเอง เสียงกรีดร้องดังลั่นชั้นเก็บคัมภีร์ ก่อนเงาหนักเงาหนึ่งจะทอดลงมาจากบันไดด้านบนอย่างช้าๆ จนทุกคนเงียบไปพร้อมกัน

ร่างนั้นสวมหน้ากากทองคำครึ่งใบ ดาบยาวในมือทาบกับต้นขาอย่างนิ่งสนิท แม้จะยังไม่ขยับ อัคคีก็รู้แล้วว่าศัตรูตรงหน้าไม่เหมือนใครในคืนนี้ อากาศทั้งชั้นเย็นลงจนเหมือนแสงเองก็ถอยหนี เขายกดาบรับ ขณะที่นักรบทองคำก้าวลงมาหนึ่งขั้น เสียงโลหะเบาๆ จากหน้ากากดังเหมือนคำพิพากษา""",
26: """ดาบแรกปะทะกันจนชั้นในหอทั้งชั้นสะเทือน แรงของนักรบทองคำหนักพอให้อัคคีลื่นถอยไปครึ่งก้าว แม้เขาจะรับทัน จังหวะถอย จังหวะกดไหล่ และมุมบิดข้อมือของอีกฝ่ายกลับคุ้นจนเลือดในกายเย็นลง เขาสวนด้วยท่าตัดต่ำที่แทบไม่มีใครนอกสายฝึกรู้จัก แต่นักรบทองคำกลับหลบได้ก่อนปลายคมเฉียดถึงเสื้อ “เจ้าเป็นใคร” อัคคีถามเสียงต่ำ คำถามถูกกลืนไปในเสียงเหล็ก เมื่ออีกฝ่ายแทงกลับด้วยท่าตอบที่เขาเคยซ้อมกับบิดาเป็นพันครั้งในวัยเด็ก

การต่อสู้นั้นจึงไม่ใช่แค่เร็ว แต่เหมือนคนสองคนอ่านหัวใจการเคลื่อนไหวกันออกหมด อัคคีเริ่มเห็นช่องเล็กๆ ของท่าฟัน รอยชะงักเพียงเสี้ยวตอนกลับมือ ลักษณะกดส้นเท้าเมื่อเตรียมหมุนตัว สิ่งเหล่านี้ไม่ควรเกิดในหุ่นหรืออาวุธไร้ใจ เขากัดฟันรับดาบอีกครั้งแล้วพูดลอยๆ ทั้งที่ไม่แน่ใจว่าอีกฝ่ายได้ยินหรือไม่ “ท่านสอนข้าไม่ให้เปิดสีข้างซ้ายเวลาถอย” มือที่กำด้ามดาบของนักรบทองคำสั่นวูบหนึ่งจริงๆ สั้นมากแต่ชัดพอจะทำให้เขาแทบลืมหายใจ

จังหวะนั้นเอง หน่วยอาคมคนสุดท้ายพยายามแทรกคาถาควบคุมจากด้านหลัง นักรบทองคำชะงักเหมือนถูกกระตุกด้วยโซ่ที่มองไม่เห็น แล้วแรงฟันถัดมาก็หนักขึ้นอย่างบ้าคลั่ง อัคคีถูกต้อนจนหลังชนชั้นคัมภีร์ไม้ เขาต้องยอมปล่อยช่องให้ปลายดาบเฉือนบ่าตัวเอง เพื่อแลกกับจังหวะสอดคมขึ้นฟันหน้ากากทองคำเต็มแรง โลหะดังแหลมบาดหู หน้ากากร้าวหนึ่งเส้น ก่อนแตกกระจายลงครึ่งหน้าเผยผิวหนังที่ถูกยันต์ทองกินลาม แต่ดวงตาคู่นั้น...ยังเป็นดวงตาที่เขาจำได้ต่อให้ผ่านไปทั้งชีวิต

เวลาหยุดนิ่งไปชั่วครู่ อัคคีไม่รู้ว่าเลือดจากบ่าหรือเลือดในหัวใจอะไรไหลมากกว่ากัน “พ่อ” คำเรียกหลุดจากปากราวมันรออยู่นานเกินไป นักรบทองคำยืนนิ่งอยู่ตรงหน้า ดวงตาที่ควรไร้ความหมายกระเพื่อมวูบเหมือนมีใครจุดไฟเล็กๆ ในเถ้าถ่าน แล้วทันใดนั้น เสียงคำสั่งจากห้องพิธีด้านล่างก็ดังขึ้นผ่านอาคม ทำให้ร่างนั้นยกดาบขึ้นจ่อคอเขาอีกครั้งด้วยมือที่สั่นอยู่เพียงน้อยนิด""",
27: """“พ่อ” อัคคีเรียกอีกครั้ง คราวนี้ไม่ดังแต่หนักกว่าดาบทั้งคืน ใบหน้าครึ่งหนึ่งของชายตรงหน้าถูกยันต์ทองกินจนแทบไม่เหลือเค้าเดิม ทว่าดวงตายังมีเศษความงุนงงคล้ายคนเพิ่งได้ยินชื่อตัวเองหลังเงียบมานาน นักรบทองคำกะพริบตาช้าๆ ดาบที่จ่อคอเขาอยู่เบี่ยงออกเพียงเส้นผมหนึ่งเส้น “อัค...คี” เสียงแหบแตกหลุดจากลำคออีกฝ่ายเหมือนคนลืมวิธีพูดไปแล้วครึ่งชีวิต แค่นั้นก็พอให้โลกทั้งใบของเขาร้าวดังลั่นโดยไม่ต้องมีใครได้ยิน

แต่สติคืนมาได้เพียงเสี้ยว หลวงวิจิตรส่งแรงอาคมจากห้องพิธีลงมากระชากร่างนักรบทองคำกลับเข้าการควบคุมทันที ชายผู้เป็นพ่อกระตุกเหมือนมีตะขอเกี่ยวอยู่ในกระดูก ดวงตาว่างเปล่าลงอีกครั้ง “หนี” คำนั้นหลุดมาเร็วมาก แล้วร่างทั้งหมดก็พุ่งเข้าใส่อัคคีใหม่ เขารับแทบไม่ทัน ความลังเลเพียงเสี้ยวทำให้โดนเฉือนแขนยาว แผลร้อนจัด แต่ในหัวเขาร้อนกว่านั้นเพราะรู้แล้วว่าถ้าปล่อยให้ใจแตกกระจายอยู่ตรงนี้ เขาจะไม่ได้ช่วยสาลิกา ไม่ได้หยุดพิธี และอาจถูกทำให้เป็นอาวุธแบบเดียวกับพ่อในที่สุด

เขาถอยไปพิงเสาหิน สูดลมหายใจครั้งยาวที่สุดในคืนพิธี คาถาลบความจำซึ่งเคยใช้กับคนอื่นนับไม่ถ้วนไหลขึ้นมาในใจอย่างน่าขยะแขยง เขาเคยเกลียดมัน แต่ตอนนี้กลับต้องหยิบมาใช้กับตัวเอง “ถ้าข้ายังเก็บทุกอย่างไว้ครบ ข้าจะยืนไม่ไหว” เขาพึมพำ นักรบทองคำชะงักอีกครั้งราวได้ยินบางอย่างจากประโยคนั้น แต่แรงอาคมก็ดึงให้ยกดาบขึ้นใหม่ อัคคีจึงตัดสินใจโดยไม่ให้ใจมีเวลาขัดขืน เขาจุดควันอาคมจากเลือดตัวเองแล้วกดมันเข้าที่ดวงตาและขมับทั้งสองข้าง

ความทรงจำส่วนหนึ่งสว่างวาบเหมือนกระดาษโดนไฟกินทีละมุม เขาไม่ได้ลืมทุกอย่าง เพียงเผาส่วนที่ทำให้มือสั่นออกชั่วคราว—ภาพเรือนเก่า เสียงหัวเราะวัยเด็ก ความอบอุ่นของฝ่ามือพ่อ ควันทำให้เขาทรุดเข่าลงครู่หนึ่งก่อนจะค่อยๆ ลุกขึ้นใหม่ด้วยดวงตาแดงจัดอย่างน่ากลัว นักรบทองคำมองเขานิ่ง ส่วนอัคคีกำดาบแน่นขึ้น แม้ความจำบางชิ้นเริ่มไหลหนีไป เขาก็ยังเหลือเป้าหมายเดียวแจ่มชัดอยู่ในอก: ไปให้ถึงสาลิกาก่อนทุกอย่างจะสายเกินแก้""",
28: """ควันอาคมย้อนเข้าตาเผาโลกให้พร่าขาวอยู่ชั่วครู่ เมื่อภาพกลับเข้าที่อีกครั้ง อัคคีรู้สึกเหมือนตัวเองเพิ่งถูกคว้านเอาอะไรบางส่วนออกจากอก ความเจ็บยังอยู่ แต่ขอบของมันเรียบขึ้นเย็นขึ้น เขามองนักรบทองคำตรงหน้าและรู้ว่าอีกฝ่ายสำคัญต่อชีวิตตนอย่างยิ่ง ทว่าเศษอบอุ่นบางชิ้นที่เคยทำให้มือเขาสั่น กลับหายไปในหมอกแล้ว สิ่งที่เหลืออยู่ชัดที่สุดคือชื่อสาลิกาและภาพห้องพิธีจากคำเล่าสุดท้ายของนาง ราววิญญาณเลือกเก็บสิ่งจำเป็นไว้เอง แม้สมองจะพยายามเผาทิ้งเพียงใด

นักรบทองคำพุ่งเข้าใส่อีกครั้ง อัคคีรับได้ดีขึ้นอย่างน่ากลัว ร่างกายที่ผ่านการฝึกมาหลายปีทำงานแทนความลังเล เขาใช้จังหวะดาบเกี่ยวแขนอีกฝ่ายให้เสียหลัก แล้วกระแทกส้นเท้าเข้าหน้าอกจนร่างใหญ่ถอยชนชั้นคัมภีร์ ทันใดนั้นเอง เสียงพิธีจากเบื้องล่างดังขึ้นแรงกว่าเดิม อักขระใต้พื้นสั่นเหมือนมีชีพ และแม้ความจำพร่า เขากลับเลือกหันลงล่างก่อนโดยแทบไม่ต้องคิด “สาลิกา” ชื่อนั้นออกจากปากเขาอย่างมั่นคงเสียจนเจ้าตัวเองยังชะงัก วูบหนึ่งนักรบทองคำลดดาบลงเหมือนเข้าใจสิ่งที่เขาเลือก

อัคคีฉวยจังหวะวิ่งผ่านไปทางบันไดชั้นใน ปล่อยให้นักรบทองคำตามมาช้าเพียงครึ่งลมหายใจซึ่งเพียงพอสำหรับคนที่กำลังแข่งกับพิธี เขาจำไม่ได้แล้วว่าตนเองตัดอะไรออกจากใจไปมากแค่ไหน แต่สิ่งหนึ่งที่ชัดคือ แม้ควันอาคมจะพรากใบหน้าบางใบและค่ำคืนบางคืนไป สิ่งที่ฝังลึกกว่านั้นกลับไม่ยอมถูกลบ เขายังเลือกช่วยใครสักคนก่อนแก้แค้นเหมือนเดิม และการเลือกนั้นคงเป็นแก่นที่คาถาใดแตะไม่ถึง

เมื่อเขาผลักประตูชั้นในออก เมืองทั้งเมืองก็เหมือนสะดุ้งพร้อมกันจากที่ไกลๆ ยันต์มหาลืมเริ่มหายใจจริงแล้ว เสียงคนร้องสับสนจากภายนอกเล็ดลอดเข้ามาตามทางอาคมเหมือนลมคร่ำครวญทั้งพระนคร อัคคียกดาบขึ้นอีกครั้ง มองแสงแดงจากห้องพิธีที่ส่องออกมาตามรอยประตู และก้าวเข้าไปหาสิ่งที่จะตัดสินว่าความทรงจำของผู้คนจะเหลืออยู่หรือไม่หลังคืนนี้""",
29: """คนทั้งเมืองหยุดพร้อมกันเมื่อยันต์มหาลืมเริ่มทำงานเต็มลมหายใจ แม่ค้าค้างช้อน เด็กค้างคำร้อง ชายชรากลางถนนทำหน้าว่างเปล่าราวเพิ่งตื่นในโลกที่ไม่รู้จักชื่ออะไรสักอย่าง ในห้องพิธีใต้หอ สาลิกากัดฟันจนเลือดซึมริมฝีปากเพื่อค้ำช่องเล็กๆ ให้ความลืมไม่ถาโถมลงเต็มแรง นางรู้สึกเหมือนตัวเองกำลังใช้เปลือกตากันน้ำหลาก แต่ก็ยังดีกว่าปล่อยให้เมืองจมในครั้งเดียว หลวงวิจิตรยืนมองความปั่นป่วนอันเงียบงันนั้นด้วยความสงบประหลาด “เห็นหรือยัง” เขาพูด “เมื่อคนไม่ต้องแบกอดีต เขาก็ไม่ทำร้ายกันด้วยมัน” 

“ท่านไม่ได้เอาความเจ็บไป” สาลิกาตอบทั้งที่แทบหายใจไม่ทัน “ท่านแค่เอาคนออกจากความเจ็บของตัวเองจนไม่เหลือใคร” หลวงวิจิตรยิ้มบางเหมือนครูฟังศิษย์พูดผิดแล้วไม่ถือสา เขาเริ่มร่ายอาคมอีกชั้นเพื่อเร่งพิธี ทันใดนั้นประตูห้องในก็เปิดผาง อัคคีวิ่งฝ่าเข้ามาพร้อมเลือดเต็มแขนและดวงตาแดงผิดมนุษย์ เขาเห็นสาลิกากลางวงยันต์ก่อนสิ่งอื่นใด ราวโลกทั้งห้องถูกตัดให้เหลือเพียงจุดเดียว ชายหนุ่มไม่เสียเวลาเอ่ยชื่อศัตรู เขาพุ่งเข้าไปฟันเส้นอาคมชุดแรกขาดทันที

แรงสะท้อนส่งเขากระเด็นไปด้านข้าง แต่ก็พอให้สาลิกาหายใจได้ลึกขึ้นนิดหนึ่ง หลวงวิจิตรชักสีหน้าเป็นครั้งแรก “เจ้ากล้าใช้คาถากับตัวเอง” เขาว่า อัคคีลุกขึ้นช้าๆ “ถ้าข้าไม่ทำ เมืองคงเหลือแต่คนเชื่อคำท่าน” เสียงเขาเย็นลงอย่างแปลกประหลาดจนแม้สาลิกายังใจหาย ชายชราหรี่ตา รับรู้ทันทีว่าคนตรงหน้าไม่ใช่อาวุธเชื่องเดิมอีกแล้ว เขาจึงเปลี่ยนเป้าหมาย “ถ้าอย่างนั้น เราจะเริ่มจากลบตัวตนของเจ้าก่อน ให้คนทั้งเมืองจำไม่ได้แม้แต่ชื่อของคนที่ขัดขืน” 

อาคมสายใหม่พุ่งเข้าหาอัคคีโดยตรง มันไม่ใช่การฆ่า แต่เป็นการลบชื่อ ลบภาพ ลบร่องของความเป็นมนุษย์จากสายตาคนอื่น สาลิกาดิ้นกับสายรัดจนข้อมือถลอก “อัคคี ระวัง!” เขาหันมาเพียงเสี้ยวเดียวพอให้สายตามาบรรจบกัน ก่อนยกดาบขึ้นรับเวทนั้นกลางอก รู้ดีว่าจากนี้เขาไม่ได้สู้แค่เพื่อชีวิตหรือความจริง หากสู้เพื่อสิทธิพื้นฐานที่สุด—การไม่ยอมให้ใครตัดสินว่าตนควรถูกลืมหรือไม่""",
30: """ห้องพิธีทั้งห้องสั่นด้วยเสียงอาคมสองสายปะทะกัน หลวงวิจิตรยืนอยู่หลังแท่นยันต์เหมือนผู้พิพากษาบนบัลลังก์ เขาไม่รีบเข้าดาบหรือเข้าตัว เพราะเชื่อว่าคำพูดยังคุมคนได้ดีกว่าเหล็ก “เจ้าคิดว่าประชาชนอยากจำทั้งหมดจริงหรือ” เขาถามอัคคี “ความจริงทำให้คนฆ่ากันมานักต่อนัก สิ่งที่ข้าทำก็แค่ตัดเชื้อไฟก่อนลาม” อัคคีหายใจหนัก เลือดจากแผลเก่าหยดลงพื้นอักขระทีละหยด “เชื้อไฟไม่เคยหายเพราะปิดตาคน” เขาตอบ “มันแค่ลามอยู่ในมือคนที่บอกว่าตนคุมได้” ประโยคนั้นทำให้สาลิกาเงยหน้าขึ้น แม้เจ็บจนมองภาพซ้อน นางก็ยังเห็นว่าคนตรงหน้าเริ่มพูดไม่เหมือนชายที่พบในตรอกฝนแดงอีกแล้ว

หลวงวิจิตรสะบัดมือ เส้นอาคมอีกชุดพุ่งไปทางสาลิกาโดยจงใจให้เป็นตัวล่อ อัคคีเลือกแทบไม่ต้องคิด เขาทิ้งจังหวะเข้าหาชายชราแล้วหมุนกลับไปกันหน้าสาลิกาแทน แรงเวทกระแทกแผ่นหลังเขาจนทรุดเข่าลง แต่ก็ดึงเวลาให้นางได้หายใจและตั้งสติ “ท่านนี่มันโง่เรื่องสำคัญจริงๆ” สาลิกากระซิบทั้งน้ำเสียงสั่น เขาไม่หันกลับ เพียงตอบสั้น “ยังดีที่ไม่โง่ซ้ำทางเดิม” คำตอบนั้นเกือบทำให้นางหัวเราะ แม้รอบตัวกำลังพังทั้งห้อง

เมื่อเส้นรัดคลายลงเล็กน้อย สาลิกาก็ใช้แรงที่เหลือช่วยคุมยันต์ให้เอียงออกจากตัวชาวเมือง กลายเป็นช่องแคบๆ ที่อัคคีใช้พุ่งเข้าใส่หลวงวิจิตรได้ในที่สุด ชายชรารับด้วยคทาอาคม โลหะกระทบกันดังแหลม คำสอนเรื่องเมตตาและระเบียบทั้งชีวิตเหมือนถูกย่อลงมาเหลือการต่อสู้ระยะประชิดกลางสัญลักษณ์แดงบนพื้น “เจ้ารู้ไหมว่าข้าเห็นเมืองจำทุกอย่างแล้วเผากันเองมาอย่างไร” หลวงวิจิตรถามกดเสียงต่ำ “ข้าไม่สนว่าท่านเห็นอะไร” อัคคีสวนกลับพร้อมกดดาบลง “ข้าสนว่าท่านทำอะไรกับคนที่ไม่ได้เลือก” 

แรงปะทะครั้งสุดท้ายก่อนศึกตัดสินทำให้หน้ากากทองคำเหนือแท่นสั่นโครม ระฆังเงินสั่นตามเป็นเสียงคมกริบไปทั้งห้อง อัคคีถอยตั้งหลัก ส่วนหลวงวิจิตรยกอาคมขึ้นเต็มมือ ดวงตาของทั้งคู่มองกันอย่างรู้ว่าไม่มีถ้อยคำใดพอแล้ว ข้างนอก ผู้คนทั้งเมืองยังยืนงงอยู่ท่ามกลางความลืมที่กำลังคืบคลาน ส่วนข้างใน ดาบกับอาคมกำลังจะตัดสินว่าใครมีสิทธิเรียกสิ่งนั้นว่าความเมตตา""",
31: """ท่ามกลางเสียงอาคมแตกกระจาย มือของบิดา—มือที่เหลือเนื้อคนอยู่เพียงบางส่วน—สั่นอยู่บนด้ามดาบอย่างเห็นได้ชัด นักรบทองคำไม่พุ่งเข้าใส่อัคคีทันทีเหมือนถูกสองคำสั่งฉีกคนละทาง อัคคีหอบอยู่กลางวงพิธี เลือดและควันอาคมทำให้ภาพข้างหน้าสั่นไหว แต่เมื่อเห็นมือนั้น เขากลับจำบทเรียนเก่าได้ชัดอย่างประหลาด: เวลารับแรงเหนือกว่า อย่าดันตรง ให้พามันเฉไปหาจุดที่เจ้าคุมได้เอง เสียงบิดาในอดีตผุดขึ้นมาเพียงเสี้ยว ทว่าเสี้ยวนั้นพอจะกลายเป็นสะพานข้ามความพร่าในหัวได้

นักรบทองคำขยับเข้ามาช้าๆ แล้วพูดด้วยเสียงฝืดแตก “ดาบ...ไม่ผิด” คำพูดห้วนเกือบไม่เป็นประโยค แต่พอให้หัวใจอัคคีรัดแน่นขึ้นอีกครั้ง เขายกดาบขึ้นรับ ขณะที่อีกฝ่ายพุ่งเข้าใส่ คราวนี้เขาไม่ต้านแรงตรงๆ กลับปล่อยให้คมของบิดาเฉียดผ่านแล้วใช้การหมุนข้อมือเล็กน้อยพาเส้นอาคมจากแท่นกลางย้อนทิศไปกระแทกกำแพงด้านหลัง หลวงวิจิตรหันขวับทันที “หยุดมัน!” ชายชราตวาดครั้งแรกในเรื่องทั้งหมด น้ำเสียงหลุดจากความสุภาพเสียจนเหมือนหน้ากากอีกใบเพิ่งแตกตาม

อัคคีเริ่มเห็นแบบของพิธีชัดขึ้น เส้นอาคมทุกเส้นล้วนกินความทรงจำเป็นเชื้อและปล่อยความว่างเป็นผล หากเบี่ยงมันกลับไปยังต้นกำเนิด คนที่ยืนป้อนมันอยู่ก็ต้องรับสิ่งที่ขังไว้ด้วย เขาเปลี่ยนท่าดาบเป็นชุดที่บิดาเคยสอนในวันฝนตกเก่าๆ ร่างกายจำได้แม้หัวจะพร่า นักรบทองคำเองก็ดูเหมือนจงใจเปิดช่องเล็กๆ ให้หลายครั้ง ทั้งที่ยังถูกยันต์คุมอยู่ “พ่อจำเจ้าได้...” อีกฝ่ายพูดหลุดมาเบาจนแทบจมในเสียงระฆัง “เท่านี้ก็พอแล้ว” ประโยคนั้นเกือบทำให้อัคคีเสียจังหวะ แต่เขาฝืนกลืนมันลงไป เพราะยังไม่ถึงเวลาพัง

เขาย้อนศรอาคมได้สำเร็จเพียงครึ่งเดียวในรอบแรก ทว่าครึ่งนั้นก็พอให้เส้นยันต์บางส่วนลุกกลับเป็นสีดำ หลวงวิจิตรถอยหลังหนึ่งก้าวเป็นครั้งแรก ดวงตาฉายความไม่เชื่อชัดเจน อัคคียืนหอบอยู่ท่ามกลางแสงวูบวาบ รู้ว่าเขายังไม่ชนะ แต่ก็รู้แล้วว่าพิธีนี้ไม่ได้คงกระพัน และคนที่ถูกทำให้เป็นอาวุธยังมอบประกายไฟสุดท้ายให้เขาใช้สู้กลับได้จริง""",
32: """เมื่ออาคมสะท้อนกลับเข้าหาแกนพิธี ความทรงจำที่ถูกกดทับไว้ทั้งระบบก็เริ่มไหลย้อนเข้าหาต้นตอเหมือนน้ำเสียทะลักกลับท่อ หลวงวิจิตรชะงักก่อนยกมือกุมขมับ ภาพจากอดีตที่เขาพยายามปิดผนึกทั้งชีวิตฉายวาบผ่านม่านตา—ไฟสงคราม ผู้คนเหยียบกันหนี เด็กตายคาอ้อมแขนหญิงร้องไห้ และชายหนุ่มในวันนั้นที่ตัดสินใจว่าถ้ามนุษย์จำมากเกินไป เมืองจะต้องพังอีกแน่ เขาถอยหลังเซแต่ยังฝืนยืน “ไม่...นี่คือสิ่งที่ข้ากันมันไว้” เขาพูดเหมือนอธิบายกับตัวเองมากกว่าใคร

อัคคีก้าวเข้าไปทีละก้าว ดาบในมือไม่ได้ยกสูงอย่างผู้ชนะ หากถือไว้ต่ำเหมือนกำลังบังคับไม่ให้มันกลายเป็นคำตอบเดียว “ท่านไม่ได้กันมันไว้” เขาบอก “ท่านขังมันไว้ให้คนอื่นรับแทน” หลวงวิจิตรหัวเราะแห้ง แล้วภาพอีกชุดก็พุ่งเข้าใส่เขา—ใบหน้าผู้คนที่ถูกลบ ชื่อที่ถูกขีดฆ่า ห้องทดลองใต้ดิน และดวงตาของเด็กที่จำแม่ตัวเองไม่ได้ ชายชราทรุดลงกับพื้นอักขระ ทั้งความเชื่อทั้งชีวิตเริ่มเน่าออกมาจากรอยร้าวที่ตนสร้างเอง

นักรบทองคำใช้แรงเฮือกสุดท้ายปักดาบลงตรงจุดเชื่อมแกนพิธีตามช่องที่อัคคีเปิดไว้ อาคมทั้งห้องร้องลั่นเหมือนสิ่งมีชีวิตถูกแทงใจ แสงแดงแตกกระจายขึ้นสู่เพดาน ระฆังเงินร่วงลงพื้นทีละใบ หลวงวิจิตรเงยหน้ามองอัคคีด้วยสายตาว่างพร่า “เมืองจะจำ...แล้วเกลียดกันเอง” อัคคีตอบเพียง “อย่างน้อยมันก็เป็นสิทธิของเมือง” คำพูดนั้นจบพร้อมกับที่แกนพิธีแตกสนั่น แรงสะเทือนอัดทุกคนปลิวออกคนละทิศ

หอจดหมายเหตุเริ่มถล่มจากฐานขึ้นมาอย่างรวดเร็ว ฝุ่นคัมภีร์กับหินแตกปลิวเต็มอากาศ สาลิกาพยายามพยุงตัวขึ้นจากแท่น ขณะที่อัคคีหันไปมองนักรบทองคำ ผู้เป็นพ่อยืนอยู่ท่ามกลางแสงล่มสลายเหมือนเงาชายคนเดิมกำลังถูกดึงออกจากเครื่องทรมานทั้งชีวิตพร้อมกัน ศัตรูหลักพ่ายแล้ว แต่หากไม่ออกไปตอนนี้ พวกเขาก็จะกลายเป็นศพในความจริงที่เพิ่งแย่งกลับมาเอง""",
33: """เมื่อหอจดหมายเหตุถล่ม เศษคัมภีร์นับร้อยปลิวออกสู่ลานเมืองเหมือนฝนสีดำ ผู้คนที่ยืนงงอยู่ตามถนนเริ่มสะดุ้งทีละคน ราวความทรงจำที่ถูกกดไว้เปิดกลับพร้อมกลิ่นฝุ่นกระดาษและอาคมไหม้ บางคนจำชื่อคนหายได้ขึ้นมาทันทีแล้วทรุดร้องไห้ บางคนเห็นหน้าญาติที่เคยว่างในหัวกลับมาชัดเสียจนต้องกุมอก มันไม่ใช่การคืนความจริงอย่างงดงามเลย หากเป็นการฉีกผ้าปิดแผลออกทั้งผืน แต่ถึงอย่างนั้น เมืองก็ยังหายใจในฐานะตัวเองอีกครั้ง

สาลิกาฝืนประคองอัคคีออกมาถึงทางเชื่อมด้านนอก ขณะที่หินด้านบนยังร่วงไม่หยุด เขาแทบมองไม่ชัดแล้วว่าตัวเองเจ็บตรงไหนบ้าง รู้เพียงว่านักรบทองคำยังตามมาใกล้ๆ ด้วยท่าทางช้าลงทุกขณะ เบื้องหลังพวกเขา แกนพิธีส่งเสียงครางรุนแรงเหมือนกำลังจะระเบิดอีกระลอก “ไป!” สาลิกาตะโกน แต่ยังไม่ทันก้าวพ้นลาน หินและอาคมก็กวาดลงมาพร้อมกัน อัคคีหันกลับได้เพียงครึ่งตัว ร่างของบิดาก็พุ่งเข้ามาผลักเขาออกไปเต็มแรงแทน

แรงระเบิดซัดอัคคีกระเด็นจนกลิ้งไปกับพื้นลาน เมื่อเงยหน้าขึ้นอีกที เขาเห็นนักรบทองคำยืนรับอาคมแตกตัวอยู่ตรงรอยแยก ร่างใหญ่สั่นเทาเหมือนโลหะจะปริออกจากข้างใน “พ่อ!” เขาลุกพรวดทั้งที่ขาแทบทรยศ สาลิกาคว้าแขนเขาไม่อยู่ เขาวิ่งฝ่าฝุ่นกลับไปหาคนตรงนั้น ขณะที่รอบเมืองเริ่มมีเสียงร้องเรียกชื่อกันดังขึ้นทุกสารทิศ—ชื่อของคนหาย คนตาย และคนที่เคยถูกลบหายไปจากหัวหมู่กำลังไหลกลับสู่เจ้าของทีละคำ

อัคคีรับร่างบิดาไว้ได้ก่อนอีกฝ่ายจะล้มสนิท ทองตามผิวแตกเป็นสะเก็ดลงบนแขนเขาเหมือนใบไม้แห้งยามหมดฤดู นักรบทองคำที่คนทั้งเมืองไม่เคยรู้ชื่อ กำลังกลับมาเป็นเพียงพ่อคนหนึ่งในอ้อมแขนลูกชั่วครู่ และนั่นช่างโหดร้ายพอๆ กับงดงามในเวลาเดียวกัน""",
34: """บิดาได้สติชัดที่สุดเพียงช่วงสั้นเท่าลมหายใจไม่กี่ครั้งในอ้อมแขนของอัคคี ดวงตาที่เคยแข็งเป็นอาวุธคลายลงจนเห็นแววคนเดิมซึ่งหายไปนานเหลือเกิน ชายร่างใหญ่พยายามยกมือขึ้นแตะแก้มลูก แต่มือสั่นมากจนทำได้เพียงครึ่งทาง อัคคีจึงประคองมันมาวางเอง ความอุ่นที่ส่งผ่านมาน้อยนิดนั้นกลับหนักเสียยิ่งกว่าคำสั่งหรือคำสาบานทั้งชีวิต “ข้า...ขอโทษ” บิดาพูดช้าๆ เหมือนแต่ละพยางค์บาดคอ “ที่ปล่อยให้เจ้าตามเศษของข้ามาไกลเพียงนี้” 

อัคคีส่ายหน้าแรงเกินจำเป็นราวถ้าช้ากว่านั้น น้ำตาจะหลุดก่อน “อย่าพูด” เขาแทบกระซิบ ชายผู้เป็นพ่อหัวเราะเบามาก แหบจนแทบไม่มีเสียง “เมื่อก่อนเจ้าไม่ฟังข้าก็ไม่ยอมเงียบ ตอนนี้จะมาห้ามกันหรือ” มันเป็นถ้อยคำธรรมดาเหลือเกิน แต่มันทำให้อัคคีแทบพัง เพราะนี่คือภาษาของบ้าน ไม่ใช่ภาษาของอาวุธ “ดาบ...ไม่ผิด” บิดาพูดอีกครั้ง ดวงตามองตรงเข้ามา “อย่าเป็นเหมือนข้า และอย่าปล่อยให้ใครเอาชื่อคนอื่นไปซ่อนอีก” คำสอนสุดท้ายไม่สวย ไม่ยาว แต่พอให้ลูกชายเก็บไปทั้งชีวิต

รอยยันต์ทองบนผิวเริ่มแตกออกเป็นผุยผงจริงๆ สาลิกาคุกเข่าลงข้างกัน หลับตาคำนับให้คนที่ถูกพรากชื่อมานานก่อนเงยหน้ามามองอัคคีอย่างเงียบงัน ไม่มีกลอนปลอบใดเหมาะกับวินาทีนี้ บิดากระชับมืออัคคีครั้งสุดท้าย เหมือนส่งแรงเล็กๆ ที่เหลืออยู่ทั้งหมดผ่านฝ่ามือ แล้วร่างทั้งร่างก็แตกสลายเป็นเกล็ดทองละเอียดปลิวไปกับลมเช้า เหลือเพียงหน้ากากทองคำครึ่งใบตกค้างอยู่บนมือของลูกชาย

อัคคีนั่งนิ่งอยู่ท่ามกลางฝุ่นหอถล่มและเสียงคนเมืองที่ค่อยๆ จำกันกลับมา หน้ากากในมือเย็นจัดจนเหมือนดึงความร้อนทั้งหมดออกจากเขาไปแล้ว สาลิกาไม่ได้แตะต้องตัวเขาในทันที เพียงนั่งอยู่ข้างกันเป็นพยานให้ความสูญเสียครั้งนี้ไม่หายไปเหมือนคืนก่อนๆ ครั้นเมื่ออัคคีลุกขึ้นในที่สุด เขาก็ยืนขึ้นพร้อมสิ่งหนึ่งที่หนักกว่าอดีต—หน้าที่จะไม่ยอมให้การตายนี้ถูกลบซ้ำอีก""",
35: """หลายวันหลังหอจดหมายเหตุถล่ม พระนครยังมีกลิ่นฝน เหล็ก และขี้เถ้าค้างอยู่ตามตรอก ผู้คนเริ่มจำกันได้มากขึ้น แต่การจำกลับมาไม่ได้แปลว่าทุกอย่างกลับดี บางบ้านต้องไว้อาลัยคนที่เพิ่งจำได้ว่าหายไป บางคนต้องอยู่กับความจริงว่าตัวเองเคยช่วยระบบลบคนอื่นอย่างไม่รู้ตัว อัคคีเดินผ่านเมืองเดิมเหมือนคนแปลกหน้าที่รู้ทางทุกสายแต่ไม่แน่ใจว่าเหลือบ้านให้กลับหรือไม่ ดวงตาของเขายังติดแดงเพลิงเล็กน้อยจากควันอาคม จนเด็กบางคนมองแล้วหลบหลังแม่โดยสัญชาตญาณ

ผู้มีอำนาจชุดใหม่เชิญเขาเข้าพบในเรือนชั่วคราวหลังหนึ่ง เสนอทั้งตำแหน่ง ผู้คุมการฟื้นฟู และสิทธิชำระชื่อให้กลับเป็นขุนนางผู้กอบกู้เมือง “บ้านเมืองยังต้องการคนอย่างเจ้า” ขุนนางหนุ่มพูดอย่างเกรงใจปนคาดหวัง อัคคีมองหน้ากากทองคำที่วางอยู่ข้างตัวแล้วตอบเรียบ “เมืองต้องการคนจำได้ว่าตัวเองทำอะไรไว้ มากกว่าต้องการมีดเล่มใหม่” คนฟังนิ่งไปก่อนเปลี่ยนเป็นข้อเสนอเรื่องชื่อเสียง เกียรติ และอำนาจใช้ป้องกันคนอื่น แต่เขาเพียงส่ายหน้า เพราะรู้ดีว่าเครื่องแบบเปลี่ยนสีไม่ได้แปลว่ามือที่ถือมันจะเปลี่ยนตามเสมอไป

เมื่อออกจากเรือนนั้น เขาพบสาลิการออยู่ใต้ต้นลำพู นางถือสมุดใหม่ปกผ้าธรรมดา แทนสมุดลับสีดำเล่มเดิมที่เกือบเอาชีวิตทุกคน “เขาอยากให้ท่านกลับไปอยู่ในกรอบเดิมหรือ” นางถาม อัคคีหัวเราะบางๆ “แค่ทาสีกรอบใหม่” สาลิกามองหน้าเขาครู่หนึ่งแล้วพยักหน้า “ข้าก็คิดไว้แล้วว่าท่านคงไม่อยู่” นางบอกว่าเริ่มรวบรวมคำให้การของผู้รอด เพื่อทำบันทึกความจริงชุดใหม่ของเมือง เขาฟังเงียบๆ รู้สึกทั้งโล่งและเจ็บที่มีคนทำสิ่งนี้ต่อได้ โดยไม่ต้องใช้ดาบทุกครั้งเหมือนเขา

พอเย็น เขาจึงส่งคำปฏิเสธอย่างเป็นทางการกลับไปโดยไม่แก้แม้คำเดียว หน้ากากทองคำถูกผูกห้อยข้างเอวแทนตราประจำตำแหน่ง เขามองกำแพงพระนครยามแสงสุดท้ายแล้วรู้ว่าไม่มีชื่อใหม่ใดที่เมืองจะมอบให้สำคัญเท่าการเลือกเส้นทางของตัวเองอีกแล้ว""",
36: """อัคคีออกเดินทางจากพระนครในคืนที่ถนนเงียบกว่าทุกครั้ง หน้ากากทองคำครึ่งใบห้อยกระทบข้างเอวเบาๆ ตามจังหวะก้าว เขาไม่สวมเครื่องแบบรัฐแล้ว เหลือเพียงเสื้อคลุมเข้ม ดาบเก่า และดวงตาที่มีรอยแดงเพลิงซึ่งทำให้คนแปลกหน้าบางรายชะงักก่อนเข้ามาขอความช่วยเหลือ ข่าวลือเริ่มเรียกเขาว่าผู้คืนความทรงจำ แม้เจ้าตัวไม่เคยตั้งชื่อนั้นให้ตัวเองเลยสักครั้ง เขาเพียงไปตามที่มีคนหายชื่อ หายหน้า หรือถูกทิ้งไว้กับความว่างที่ไม่ใช่ของธรรมชาติ แล้วทำเท่าที่ทำได้โดยไม่รับคำขอบคุณมากเกินจำเป็น

ในหมู่บ้านเล็กนอกกำแพง เขาช่วยเด็กชายคนหนึ่งจำได้ว่าแม่ตายไปแล้ว ไม่ได้หายตัวจากเขาอย่างไร้เหตุผล เด็กคนนั้นร้องไห้จนตัวโยน ก่อนเงยหน้าถามทั้งน้ำตา “ถ้าจำแล้วเจ็บ ทำไมต้องจำ” อัคคีนั่งยองลงระดับเดียวกัน คำตอบไม่มาง่ายเหมือนออกคำสั่งสนามรบ เขาเงียบอยู่พักหนึ่งก่อนบอก “เพราะถ้าไม่จำ คนที่หายไปจะเหมือนไม่เคยมีอยู่จริง” เด็กยังร้องอยู่ แต่พยักหน้าเบาๆ แล้วกอดผ้าของแม่ไว้แน่นขึ้น อัคคีวางมือบนบ่าเล็กนั้นอย่างแผ่วกว่าที่ตนเคยทำกับใครเมื่อก่อน

ในพระนคร สาลิกาเริ่มจดบันทึกคำให้การของผู้รอดเป็นชุดใหม่ นางส่งสำเนาบางส่วนให้เขาผ่านคนเดินสารเป็นครั้งคราว หน้าแรกของเล่มล่าสุดมีเพียงประโยคสั้นๆ ว่า ‘ความจริงไม่ทำให้แผลหาย แต่มันกันไม่ให้ใครขโมยแผลนั้นไปอ้างแทนเรา’ เขาอ่านแล้วพับเก็บไว้กับตัวอย่างระวังพอกับที่ครั้งหนึ่งเคยเก็บหลักฐานลับ พวกเขาไม่ได้เดินร่วมทางกันทุกก้าวอีกต่อไป แต่ต่างก็ทำหน้าที่คนละด้านของสิ่งเดียวกัน—คนหนึ่งออกตามหาความจำที่ร่วงหล่น อีกคนคอยบันทึกไม่ให้มันสูญไปซ้ำ

ก่อนรุ่งสาง อัคคีหยุดบนสันถนน มองแสงแรกค่อยๆ ดันเงาออกจากนาและคลองด้านหน้า เขาช่วยคนอื่นดึงชื่อที่หายไปกลับมาได้หลายชื่อแล้ว แต่ในตัวเขาเองก็ยังมีช่องว่างบางส่วนที่ควันอาคมเผาไว้ ไม่มีทางปิดสนิทอีก เขาแตะหน้ากากทองคำข้างเอวเพียงครู่หนึ่ง เหมือนคำนับให้คนตาย คนรอด และตัวเองในร่างเดิม จากนั้นก็เดินต่อเข้าเงามืดที่ยังเหลืออยู่เบื้องหน้า ไม่ใช่ในฐานะมือปราบของใครอีกแล้ว หากในฐานะคนคนหนึ่งที่ยอมแบกความจริงไว้ แม้มันจะหนักจนไม่มีวันเดินสบายเหมือนเดิมก็ตาม""",
}


def effective_pov(scene: dict, ep: int):
    raw = scene['POV']
    if 'สลับ' not in raw:
        return raw
    overrides = {
        23: 'สาลิกา',
        24: 'ขุนอัคคี',
        29: 'สาลิกา',
        30: 'ขุนอัคคี',
        33: 'สาลิกา',
        34: 'ขุนอัคคี',
    }
    return overrides.get(ep, 'ขุนอัคคี')


def split_core(ep: int):
    return [p.strip() for p in PROSE[ep].strip().split('\n\n') if p.strip()]


def short_name(name: str):
    if 'ขุนอัคคี' in name or name == 'อัคคี':
        return 'อัคคี'
    if 'สาลิกา' in name:
        return 'สาลิกา'
    if 'หลวงวิจิตร' in name or 'วิจิตร' in name:
        return 'หลวงวิจิตร'
    if 'ภาสกร' in name or 'นักรบทองคำ' in name or 'บิดา' in name:
        return 'นักรบทองคำ'
    if 'พวงคำ' in name:
        return 'แม่ครูพวงคำ'
    if 'ชยุต' in name:
        return 'ชยุต'
    if 'มะลิ' in name:
        return 'มะลิ'
    if 'คนทรยศ' in name:
        return 'ชายคนนั้น'
    return name.strip()


