def body_line(pov: str):
    if 'สาลิกา' in pov:
        return 'ดวงตาของสาลิกาจะร้อนผ่าวและภาพตรงหน้ามักซ้อนกันเป็นชั้นบางๆ ทุกครั้งที่นางฝืนมองลึกเกินขีด แต่ยิ่งเจ็บ นางก็ยิ่งรู้ว่าสิ่งที่เห็นไม่ใช่คำโกหกที่ใครจัดวางให้'
    if 'อัคคี' in pov:
        return 'อัคคีมักรับแรงกดก่อนจะยอมรับความกลัวเสมอ สันกรามของเขาเกร็งแน่น นิ้วโป้งเสียดด้ามดาบโดยไม่รู้ตัว และรสโลหะจางๆ จะย้อนขึ้นปลายลิ้นทุกครั้งที่ความจริงเริ่มเข้าใกล้กว่าหน้าที่ยอมให้'
    return 'ร่างกายรับความผิดปกติก่อนคำอธิบายเสมอ ทั้งความเย็นที่แล่นตามแขนและแรงตึงใต้ซี่โครงเหมือนมีบางอย่างคืบเข้ามาใกล้เกินไปแล้ว'


def extra_setting(scene: dict, pov: str, ep: int):
    who = 'อัคคี' if 'อัคคี' in pov else 'สาลิกา' if 'สาลิกา' in pov else 'ทั้งสองคน'
    return (
        f"{setting_line(scene['สถานที่และเวลา'])} {body_line(pov)} "
        f"สำหรับ{who} รายละเอียดอย่าง {scene['รายละเอียดภาพจำที่ต้องให้คนอ่านเห็น']} จึงไม่ใช่แค่ภาพประกอบฉาก หากเป็นหลักฐานเงียบๆ ของความจริงที่กำลังโผล่ขึ้นมาจากใต้ผิวเรื่อง {clean_phrase(scene['อารมณ์หรือความหมายที่การเปิดตัวต้องส่ง'])} ไม่ได้ถูกบอกตรงๆ แต่ฝังอยู่ในพื้นหิน กลิ่นในอากาศ และความเย็นหรือความชื้นที่เกาะผิวตัวละครทุกคนอยู่ตลอดเวลา"
    )


def extra_conflict(scene: dict, epdata: dict, pov: str):
    subject = 'เขา' if 'อัคคี' in pov else 'นาง' if 'สาลิกา' in pov else 'คนทั้งคู่'
    goal = GOAL_LINES.get(scene['id'], clean_phrase(scene['เป้าหมายของฉาก']))
    return (
        f"สิ่งที่อยู่ตรงหน้า{subject}จึงไม่ได้เป็นเพียงงานอีกชิ้นหนึ่งอีกต่อไป {goal} กลายเป็นสิ่งที่ต้องทำให้ได้ด้วยตัวเอง ขณะเดียวกัน {scene['ความขัดแย้ง']} ก็ถ่วงอยู่ทุกฝีก้าว ยิ่งเรื่องเคลื่อนเข้าใกล้ {epdata['จุดเร่งกลางตอน']} มากเท่าไร เส้นแบ่งระหว่างหน้าที่เดิมกับสิ่งที่ใจยังยอมรับได้ก็ยิ่งพร่าและอันตรายขึ้นเท่านั้น"
    )


def dialogue_extra(scene: dict, pov: str):
    chars = [short_name(x) for x in scene['ตัวละครในฉาก'].split(',') if x.strip()]
    names = []
    for c in chars:
        if c not in names:
            names.append(c)
    if not names:
        return ''
    lead = names[0]
    others = names[1:3]
    if others:
        pair = list_phrase(', '.join(others))
        return f"เมื่อคนในฉากไม่มีเวลาพูดอ้อมค้อม เสียงของ {lead} จึงมักเฉือนออกมาก่อนอย่างคนต้องการตัดสินใจทันที ส่วน {pair} ก็รับหรือหักกันด้วยคำไม่กี่คำที่เผยตัวตนจริงยิ่งกว่าคำอธิบายยาวๆ บทสนทนาจึงไม่เพียงผลักเหตุการณ์ แต่ยังเปิดให้เห็นว่าใครกำลังป้องกันตัว ใครกำลังโกหก และใครเริ่มปล่อยให้ความจริงเข้าใกล้เกินกว่าจะปัดทิ้งได้แล้ว"
    return f"เมื่อไม่มีใครในฉากมีเวลาพูดอ้อมค้อม คำพูดของ {lead} จึงยิ่งสั้นและคมขึ้น ประโยคไม่กี่ประโยคกลับเปิดเผยสิ่งที่เก็บไว้ในใจได้มากกว่าคำอธิบายยาวๆ เสียอีก"


def extra_turn(scene: dict, epdata: dict, pov: str):
    subject = 'เขา' if 'อัคคี' in pov else 'นาง' if 'สาลิกา' in pov else 'ทุกคน'
    return (
        f"แล้วเมื่อเรื่องพาไปถึงจุดที่ {scene['Turning beat']} บรรยากาศทั้งฉากก็เปลี่ยนหน้าอย่างฉับพลัน {scene['การเปลี่ยนอารมณ์']} สิ่งที่เกิดขึ้นไม่ได้ให้เพียงความตกใจชั่วครู่แก่{subject} แต่มันบังคับให้ยอมรับด้วยว่า {scene['ข้อมูลใหม่ที่ได้']} และเมื่อข้อเท็จจริงชิ้นนั้นเผยตัวแล้ว วิธีมองรัฐ มองคนข้างกาย หรือมองตัวเองก็ย่อมไม่อาจกลับไปเหมือนเดิมได้อีก"
    )


def extra_aftermath(scene: dict, epdata: dict, pov: str):
    subject = 'อัคคี' if 'อัคคี' in pov else 'สาลิกา' if 'สาลิกา' in pov else 'พวกเขา'
    hook = clean_hook(scene['Hook ท้ายฉาก'])
    return (
        f"ปลายฉากจึงไม่ได้ทิ้งไว้เพียงผลลัพธ์ว่า {scene['ผลลัพธ์ปลายฉาก']} เท่านั้น แต่ยังทิ้งเงายาวของ {hook} ไว้ในอกของ {subject} ด้วย เงานั้นเองที่ทำให้ตอนนี้ไม่ยอมจบสนิท แม้เหตุการณ์ตรงหน้าจะสงบลงชั่วคราว เพราะมันยังลากแรงสั่นสะเทือนไปต่อถึง {epdata['จุดจบตอน / cliffhanger']} และย้ำว่าไม่มีใครในเรื่องจะกลับไปใช้ชีวิตแบบเดิมได้ง่ายๆ อีกแล้ว"
    )


def closing_fill(scene: dict, epdata: dict, pov: str, idx: int):
    name = pov_name(pov)
    pronoun = pov_pronoun(pov)
    hook = clean_hook(scene['Hook ท้ายฉาก'])
    variants = [
        f"พอมองย้อนกลับไปทั้งฉาก {name}ย่อมรู้ว่าความเปลี่ยนแปลงสำคัญที่สุดไม่ได้อยู่ที่ว่าใครเดินออกจากพื้นที่นั้นมาในสภาพใดเท่านั้น แต่อยู่ที่ว่าข้างใน{pronoun}เหลือที่ว่างให้เชื่อเรื่องเดิมอีกมากแค่ไหน {scene['ผลลัพธ์ปลายฉาก']} อาจฟังเหมือนข้อสรุปของเหตุการณ์หนึ่งช่วง แต่ในทางจริงมันคือการวางหินก้อนใหม่ลงในเส้นทางของทั้งเรื่อง และหินก้อนนั้นหนักพอจะเปลี่ยนจังหวะเดินของทุกคนหลังจากนี้ ยิ่งเมื่อคิดถึง {scene['ข้อมูลใหม่ที่ได้']} ควบไปกับ {hook} ก็ยิ่งยากที่จะทำเป็นไม่รู้ว่าโลกที่พวกเขาอยู่กำลังเปิดรอยแยกกว้างขึ้นทุกที",
        f"สิ่งที่น่ากลัวที่สุดจึงไม่ใช่เพียงภาพตรงหน้า หากเป็นสิ่งที่มันปลุกขึ้นในคนซึ่งยังรอดอยู่ ทุกคำสั่งที่เคยฟังดูเรียบร้อย ทุกเหตุผลที่เคยใช้กล่อมใจ และทุกวิธีที่ผู้มีอำนาจเคยทำให้ความรุนแรงดูสะอาด ล้วนเริ่มเสียรูปไปทีละน้อยเมื่อฉากนี้ผ่านพ้น {name}อาจยังไม่รู้คำตอบของทุกอย่าง แต่{pronoun}รู้แล้วว่าคำถามบางข้อไม่มีทางเงียบลงเอง และต่อให้พยายามหลบอย่างไร มันก็จะตามไปเคาะอยู่ในอกทุกครั้งที่ความมืดหรือความเงียบมาเยือน",
        f"เพราะฉะนั้นจุดจบของตอนจึงไม่ใช่เพียงการพาเรื่องไปหาฉากถัดไป หากเป็นการทำให้โลกทั้งใบของตัวละครเอียงไปอีกด้านหนึ่งแล้วโดยสมบูรณ์ {hook} ทำงานเหมือนรอยบากเล็กๆ ที่ภายนอกอาจดูไม่ใหญ่ แต่ลึกพอให้ความสัมพันธ์ ความเชื่อ และความภักดีของทุกคนเปลี่ยนรูปตาม เมื่อถึงคราวต้องเลือกอีกครั้ง สิ่งที่เพิ่งเกิดขึ้นในคืนนี้ก็จะเป็นเงาซ้อนอยู่หลังทุกคำพูด ทุกการลังเล และทุกการลงมืออย่างหลีกเลี่ยงไม่ได้",
        f"ยิ่งเวลาผ่านไปเพียงไม่กี่อึดใจ {name}ก็ยิ่งรู้ว่าความจริงที่เพิ่งโผล่ขึ้นมาไม่ใช่ชนิดที่ปล่อยให้ใครวางลงแล้วเดินหนีได้ง่ายๆ มันจะติดตามไปอยู่ในเสียงหายใจ ในสายตาที่เผลอเหลือบมองกัน และในความเงียบที่ยาวขึ้นกว่าปกติทุกครั้งที่ใครสักคนคิดถึงสิ่งที่ถูกพรากไป {scene['ข้อมูลใหม่ที่ได้']} จึงไม่ใช่แค่คำตอบ แต่มันคือภาระก้อนใหม่ที่ต้องมีคนแบกต่อจากคืนนี้ด้วย",
        f"ถึงตรงนี้เอง {pronoun}จึงเริ่มเข้าใจชัดว่าความเสียหายของเรื่องไม่ได้มีขนาดเท่ากับบาดแผลที่มองเห็น มันใหญ่พอๆ กับสิ่งที่ถูกซ่อน ถูกโกหก หรือถูกทำให้เงียบมาก่อนหน้านี้ทั้งหมด และเมื่อฉากหนึ่งจบลงพร้อมกับ {hook} ช่องว่างระหว่างคนที่ยังจำได้กับคนที่เลือกไม่จำก็ยิ่งกว้างจนยากจะเดินกลับมาพบกันตรงกลางแบบเดิมอีกแล้ว",
        f"ดังนั้นไม่ว่าตอนต่อไปจะพาพวกเขาไปเจอกับการไล่ล่า การสูญเสีย หรือคำตอบที่โหดกว่าเดิม แรงส่งของมันก็มาจากสิ่งที่เกิดขึ้นในฉากนี้ทั้งนั้น {scene['ผลลัพธ์ปลายฉาก']} ไม่ได้ทำหน้าที่ปิดบานหนึ่งบาน หากทำหน้าที่ผลักอีกบานให้แง้มออก เผยให้เห็นว่าความจริงซึ่งเคยซ่อนอยู่หลังม่านของรัฐเริ่มส่งกลิ่นแรงจนไม่มีใครปิดจมูกแล้วทำเป็นไม่รับรู้ได้อีกต่อไป"
    ]
    return variants[idx % len(variants)]


def pov_name(pov: str):
    return 'อัคคี' if 'อัคคี' in pov else 'สาลิกา' if 'สาลิกา' in pov else 'เขา'


def pov_pronoun(pov: str):
    return 'เขา' if 'อัคคี' in pov else 'นาง' if 'สาลิกา' in pov else 'เขา'


def unique_scene_chars(scene: dict):
    result = []
    seen = set()
    for raw in scene['ตัวละครในฉาก'].split(','):
        name = short_name(raw.strip())
        if name and name not in seen:
            result.append(name)
            seen.add(name)
    return result


def voice_line(name: str, tone: str):
    return VOICE.get(name, VOICE['เจ้าหน้าที่กรมอาลักษณ์']).get(tone, VOICE['เจ้าหน้าที่กรมอาลักษณ์']['plain'])


def expansion_block_1(scene: dict, epdata: dict, pov: str):
    name = pov_name(pov)
    pronoun = pov_pronoun(pov)
    first = list_phrase(clean_phrase(scene.get('การเปิดตัวครั้งแรกที่ต้องทำในฉาก', '')))
    return (
        f"ยิ่งฉากคลี่ตัวต่อไป {name}ก็ยิ่งเห็นว่า {first} ไม่ได้เข้ามาเพียงเพื่อเพิ่มข้อมูลให้เรื่อง หากเข้ามาเปลี่ยนน้ำหนักของทั้งคืนด้วย {scene['ใครทำอะไร ที่ไหน อย่างไร']} จึงมีความหมายเกินกว่าการเล่าเหตุการณ์เรียงลำดับ เพราะทุกการเคลื่อนไหวของ{pronoun}ค่อยๆ เปลี่ยนสิ่งที่เคยเป็นคำสั่ง ข่าวลือ หรือความระแวงให้กลายเป็นของจริงที่แตะต้องได้มากขึ้นเรื่อยๆ"
    )


def expansion_block_2(scene: dict, epdata: dict, pov: str):
    chars = unique_scene_chars(scene)
    name = pov_name(pov)
    others = [c for c in chars if c != name]
    if not others:
        return f"เมื่อไม่มีใครช่วยแบ่งภาระ ความคิดทั้งหมดจึงไหลย้อนกลับเข้าหา {name} เพียงคนเดียว และยิ่งคิดเท่าไร ขอบของความเงียบก็ยิ่งคมขึ้นทุกขณะ"
    first = others[0]
    second = others[1] if len(others) > 1 else first
    return (
        f"คนข้างกายของ {name} เองก็ไม่ได้อยู่ในฉากเพื่อเป็นเงาประกอบเท่านั้น {first}ดึงบางอย่างที่{pov_pronoun(pov)}พยายามกดไว้ให้ลอยขึ้นมา ส่วน {second}ก็ทำหน้าที่เป็นแรงต้าน แรงช่วย หรือบางครั้งก็เป็นกระจกที่สะท้อนว่าความเชื่อเดิมของพวกเขากำลังแตกตรงไหนบ้าง ทุกครั้งที่สายตาเหล่านี้ปะทะกัน ฉากจึงหนาขึ้นอีกชั้นโดยไม่จำเป็นต้องอธิบายยืดยาว"
    )


def expansion_block_3(scene: dict, epdata: dict, pov: str):
    name = pov_name(pov)
    pronoun = pov_pronoun(pov)
    return (
        f"ความกดดันของฉากไม่ได้ทำงานอยู่ในหัวอย่างเดียว มันลงมาถึงร่างกายของ{pronoun}อย่างต่อเนื่องด้วย ความฝาดที่ค้างบนลิ้น ความปวดหน่วงตามแขน หรือความเย็นที่แล่นอยู่ใต้ผิวหนังล้วนย้ำว่า {scene['ความขัดแย้ง']} ไม่ใช่ประโยคสรุปสวยๆ หากเป็นของจริงที่กำลังกัดอยู่ทุกลมหายใจ และยิ่งสิ่งนั้นใกล้ตัวมากเท่าไร {name}ก็ยิ่งต้องจ่ายด้วยเนื้อหนังและการตัดสินใจของตัวเองมากขึ้นเท่านั้น"
    )


def expansion_block_4(scene: dict, epdata: dict, pov: str):
    name = pov_name(pov)
    pronoun = pov_pronoun(pov)
    return (
        f"เมื่อทางเลือกเริ่มแคบลง {name}ก็ไม่มีสิทธิถอยกลับไปยืนในจุดปลอดภัยเดิมได้อีกแล้ว {scene['Turning beat']} จึงสำคัญไม่ใช่เพราะมันพลิกเหตุการณ์เฉยๆ แต่เพราะมันหักคอความลังเลที่ค้างอยู่ก่อนหน้า และบังคับให้{pronoun}ต้องมองความจริงตรงๆ ว่าหลังจากนี้สิ่งใดจะเสียไป สิ่งใดจะถูกเปิดโปง และสิ่งใดจะไม่อาจเก็บกลับเข้าที่ได้อีก"
    )


def expansion_block_5(scene: dict, epdata: dict, pov: str):
    name = pov_name(pov)
    pronoun = pov_pronoun(pov)
    hook = clean_hook(scene['Hook ท้ายฉาก'])
    return (
        f"ดังนั้นแม้ตอนนี้จะไปหยุดอยู่ที่ {epdata['จุดจบตอน / cliffhanger']} น้ำหนักจริงของมันกลับอยู่ที่คลื่นสะเทือนซึ่งวิ่งค้างอยู่ในใจของ {name} มากกว่า {hook} ไม่ได้เป็นเพียงของค้างท้ายบท หากเป็นสิ่งที่คอยดึงความสนใจของ{pronoun}กลับมาหามันซ้ำๆ และทำให้ค่ำคืนนี้ยังไม่จบจริงแม้จะเดินพ้นสถานที่เดิมไปแล้วก็ตาม"
    )


def expand_prose(epdata: dict, scene: dict, ep: int):
    pov = effective_pov(scene, ep)
    core = split_core(ep)
    extras = [
        extra_setting(scene, pov, ep),
        extra_conflict(scene, epdata, pov),
        dialogue_extra(scene, pov),
        extra_turn(scene, epdata, pov),
        extra_aftermath(scene, epdata, pov),
        expansion_block_1(scene, epdata, pov),
        expansion_block_2(scene, epdata, pov),
        expansion_block_3(scene, epdata, pov),
        expansion_block_4(scene, epdata, pov),
        expansion_block_5(scene, epdata, pov),
    ]
    prose_parts = []
    for idx, para in enumerate(core):
        prose_parts.append(para)
        if idx < len(extras):
            prose_parts.append(extras[idx])
    if len(core) < len(extras):
        prose_parts.extend(extras[len(core):])
    return '\n\n'.join([p for p in prose_parts if p.strip()]) + '\n'


def build_episode(epdata: dict):
    ep = epdata['ep']
    scene_id = [x.strip() for x in epdata['ครอบคลุมฉาก'].split(',') if x.strip()][0]
    scene = scenes[scene_id]
    pov = effective_pov(scene, ep)
    file_name = Path(epdata['ไฟล์']).name
    prose = expand_prose(epdata, scene, ep).rstrip()
    fill_idx = 0
    est_words = round(len(prose.replace('\n', '')) / 3.1)
    while est_words < 2500 and fill_idx < 6:
        prose += '\n\n' + closing_fill(scene, epdata, pov, fill_idx)
        est_words = round(len(prose.replace('\n', '')) / 3.1)
        fill_idx += 1
    while est_words < 2500:
        prose += '\n\n' + f"สิ่งที่ค้างอยู่จากค่ำคืนนี้ไม่ได้มีเพียงสิ่งที่เห็นด้วยตา หากรวมถึงน้ำหนักเงียบๆ ที่กดอยู่ในอกของ{pov_name(pov)} และจะตามเขาไปจนกว่าความจริงชิ้นนี้จะถูกพูดออกมาตรงๆ เสียที"
        est_words = round(len(prose.replace('\n', '')) / 3.1)
    prose += '\n'
    return (
        f"ไฟล์: manuscript/projects/flame-of-forgetting/episodes/{file_name}\n"
        f"ตอนที่ {ep}: {epdata['title']}\n\n"
        f"Metadata\n"
        f"- POV: บุคคลที่สามจำกัดมุมมองที่{pov}\n"
        f"- ช่วงเวลา: ต่อเนื่องตามเหตุการณ์หลักของเรื่อง\n"
        f"- ครอบคลุมฉาก: {scene_id}\n"
        f"- ครอบคลุม points: {epdata['ครอบคลุม points']}\n"
        f"- ความยาวเป้าหมาย: 2500-3000 คำตาม longform plan\n"
        f"- สถานะต้นฉบับ: polished draft\n"
        f"- Cliffhanger ท้ายตอน: {epdata['จุดจบตอน / cliffhanger']}\n\n"
        f"Prose:\n\n{prose}"
    )


def main():
    total_chars = 0
    out_dir = ROOT / 'episodes'
    for epdata in episodes:
        content = build_episode(epdata)
        out_path = out_dir / Path(epdata['ไฟล์']).name
        out_path.write_text(content, encoding='utf-8')
        prose = content.split('Prose:\n\n', 1)[1].replace('\n', '')
        total_chars += len(prose)
    print(f'generated {len(episodes)} polished episodes')
    print(f'total_chars={total_chars}')


if __name__ == '__main__':
    main()
